# # Threshold-averaged Expected Shortfall in short samples
#
# Peaks-over-threshold estimates of value-at-risk (VaR) and Expected Shortfall (ES) depend on the threshold. This notebook averages the estimates over a grid of thresholds with several weighting schemes, compares protections against near-singular shape estimates (fitted shapes close to one, which make the ES explode), evaluates checks that recognize samples in which the ES is weakly identified, and applies everything to simulated samples, market data and insurance losses.
#
# How to run. Set the options in the first code cell, then run all cells in order. The library cells only define functions; the *Step* cells at the end do the work. In quick mode every step runs in minutes with small samples (the numbers are not meaningful); full mode takes hours, but every block is cached, so an interrupted run resumes where it stopped.
#
# Requirements. Python with numpy, scipy, pandas, matplotlib, joblib, yfinance and rdata. R with threshr, eva and mev is optional (external benchmarks).

# Settings: the only cell you normally edit.
#
# Run the notebook from a project folder; it creates data/ and outputs/ inside it.
# Data are downloaded and archived automatically if missing:
#   data/clean/<ASSET>_clean.csv          price snapshots (downloaded once with yfinance, then reused)
#   data/danish_fire_losses.csv           Danish fire losses (R package evir)
#   data/norwegian_fire_claims*.csv       Norwegian fire claims, nominal (ReIns) and at 2012 prices (CASdatasets)
#   data/simulated/                       every simulated sample (if USER_SAVE_SAMPLES)
# Results: outputs/tables/<mode>/, outputs/figures/<mode>/, outputs/cache/<mode>/ (cached blocks:
# an interrupted run resumes where it stopped) and outputs/manifest_<mode>.json.
USER_RUN_MODE = "full"      # "quick" = smoke test (minutes; small samples, numbers differ); "full" = full study (hours)
USER_N_JOBS = -1             # parallel processes (-1 = all cores)
USER_RUN_R = True            # use R (threshr, eva, mev) for the external benchmarks if Rscript is found
USER_SAVE_SAMPLES = True     # save every simulated sample to data/simulated/ (about 50 MB in full mode)



