# Insurance data
# ----------------------------------------------------------------------------------------
def run_danish():
    """Full sample (seed 1985) and each calendar year (seeds 2000 + i)."""
    def compute():
        d = load_danish()
        jobs = [("1980-1990", d["loss"].values, 1985, DANISH_B)]
        jobs += [(str(y), g["loss"].values, 2000 + i, DANISH_B) for i, (y, g) in enumerate(d.groupby("year"))]
        return pd.DataFrame(pmap(_levels_sample, jobs))
    return cached_csv(cache_dir() / f"danish_B{DANISH_B}.csv", compute)


def norwegian_samples():
    """Annual samples of the Norwegian fire claims with at least NOR_MIN_CLAIMS claims
    (1976-1992 with the default of 200), as (year, claim sizes)."""
    d = load_norwegian()
    # Within each year the claims are listed by size, not by date. Only blocked CV-BMA depends
    # on the order, and sorted data would put all large claims in its last fold, so each year
    # is put in a fixed random order (stream "NOR_ORDER", year).
    return [(int(y), stream("NOR_ORDER", int(y)).permutation(g["size"].values.astype(float)))
            for y, g in d.groupby("year") if len(g) >= NOR_MIN_CLAIMS]


def run_norwegian():
    """Each qualifying year (seeds 3000 + i), B as for the Danish data."""
    def compute():
        jobs = [(str(y), x, 3000 + i, DANISH_B) for i, (y, x) in enumerate(norwegian_samples())]
        return pd.DataFrame(pmap(_levels_sample, jobs))
    return cached_csv(cache_dir() / f"norwegian_B{DANISH_B}_min{NOR_MIN_CLAIMS}.csv", compute)


def norfire_real_samples():
    """Norwegian claims at 2012 prices (CASdatasets::norfire), years NOR_REAL_YEARS.
    The nominal priority of 500 is a different real priority in each year (500 x the CPI
    factor), so all years are cut at the largest of these, the common real priority, which
    gives a consistently truncated sample. Returns (priority, [(name, losses), ...]): first
    the pooled sample (years in order, claims of a year in a fixed random order, stream
    "NOR_REAL_ORDER"), then each year."""
    d = load_norfire()
    y0, y1 = NOR_REAL_YEARS
    d = d[(d.year >= y0) & (d.year <= y1)]
    priority = float(500 * (d.loss2012 / d.loss).max())
    d = d[d.loss2012 >= priority * (1 - 1e-12)]
    years = [(int(y), stream("NOR_REAL_ORDER", int(y)).permutation(g["loss2012"].values.astype(float)))
             for y, g in d.groupby("year")]
    pooled = np.concatenate([x for _, x in years])
    return priority, [(f"{y0}-{y1}", pooled)] + [(str(y), x) for y, x in years]


def run_norfire_real():
    """Pooled sample (seed 3100) and each year (seeds 3200 + i), B as for the Danish data."""
    def compute():
        _, samples = norfire_real_samples()
        jobs = [(nm, x, 3100 if i == 0 else 3200 + i - 1, DANISH_B) for i, (nm, x) in enumerate(samples)]
        return pd.DataFrame(pmap(_levels_sample, jobs))
    return cached_csv(cache_dir() / f"norfire_real_B{DANISH_B}.csv", compute)


def _extra_sample(kind, name, x):
    return {"kind": kind, "sample": name, "n": int(np.asarray(x).size), **extra_estimates(x, caps=CAPS_RUN)}


def run_extra_real():
    """Capped, penalised and reduced-bias Hill benchmarks for the Danish losses (full sample and
    years), the Norwegian claims at 2012 prices (pooled and years) and the nominal Norwegian
    annual samples. Deterministic (no bootstrap)."""
    def compute():
        d = load_danish()
        jobs = [("danish", "1980-1990", d["loss"].values)]
        jobs += [("danish", str(y), g["loss"].values) for y, g in d.groupby("year")]
        jobs += [("norway_real", nm, x) for nm, x in norfire_real_samples()[1]]
        jobs += [("norway_nominal", str(y), x) for y, x in norwegian_samples()]
        return pd.DataFrame(pmap(_extra_sample, jobs))
    return cached_csv(cache_dir() / "extra_benchmarks" / "real_data.csv", compute)


def export_norfire_real_samples():
    """Write the pooled real-terms Norwegian sample and each year for the R benchmark script."""
    folder = cache_dir() / "rcomp_norfire_real"
    folder.mkdir(parents=True, exist_ok=True)
    rows = []
    for i, (nm, x) in enumerate(norfire_real_samples()[1]):
        f = f"norreal_{nm}.csv"
        pd.DataFrame({"x": x}).to_csv(folder / f, index=False, float_format="%.15g")
        rows.append({"scenario": "Norwegian fire (2012 prices)", "n": x.size, "rep": 0 if i == 0 else int(nm), "file": f})
    pd.DataFrame(rows).to_csv(folder / "index.csv", index=False)
    return folder


