def export_rcomp_samples():
    """Write the first RCOMP_R stress samples of each cell for the R benchmark script (600 in full mode)."""
    folder = cache_dir() / "rcomp"
    folder.mkdir(parents=True, exist_ok=True)
    rows = []
    for d in DESIGNS:
        for n in STRESS_NS:
            for r in range(RCOMP_R):
                f = f"s_{_slug(d).replace('(', '').replace(')', '').replace(',', '')}_{n}_{r}.csv"
                pd.DataFrame({"x": simulate(d, n, r)}).to_csv(folder / f, index=False)
                rows.append({"scenario": d, "n": n, "rep": r, "file": f})
    pd.DataFrame(rows).to_csv(folder / "index.csv", index=False)
    return folder


def export_danish_samples():
    """Write the Danish full sample and each year for the R benchmark script."""
    folder = cache_dir() / "rcomp_danish"
    folder.mkdir(parents=True, exist_ok=True)
    d = load_danish()
    rows = [{"scenario": "danish", "n": len(d), "rep": 0, "file": "full.csv"}]
    pd.DataFrame({"x": d["loss"].values}).to_csv(folder / "full.csv", index=False)
    for y, g in d.groupby("year"):
        pd.DataFrame({"x": g["loss"].values}).to_csv(folder / f"y{y}.csv", index=False)
        rows.append({"scenario": "danish", "n": len(g), "rep": int(y), "file": f"y{y}.csv"})
    pd.DataFrame(rows).to_csv(folder / "index.csv", index=False)
    return folder


def export_norwegian_samples():
    """Write the Norwegian annual samples for the R benchmark script (rep = year)."""
    folder = cache_dir() / "rcomp_norwegian"
    folder.mkdir(parents=True, exist_ok=True)
    rows = []
    for y, x in norwegian_samples():
        pd.DataFrame({"x": x}).to_csv(folder / f"y{y}.csv", index=False)
        rows.append({"scenario": "norwegian", "n": len(x), "rep": y, "file": f"y{y}.csv"})
    pd.DataFrame(rows).to_csv(folder / "index.csv", index=False)
    return folder


def load_rcomp(kind="stress"):
    """Results of the R benchmark script: outputs/cache/<mode>/rcomp_out/ (stress samples) or
    rcomp_danish_out/ (Danish). Without them, stored results in data/published_rules/
    are used if present (same samples). Returns None if neither exists."""
    sub = {"stress": "rcomp_out", "danish": "rcomp_danish_out", "norwegian": "rcomp_norwegian_out",
           "norfire_real": "rcomp_norfire_real_out"}[kind]
    files = sorted((cache_dir() / sub).glob("part*.csv"))
    if files:
        return pd.concat([pd.read_csv(f) for f in files], ignore_index=True)
    stored = DATA_DIR / "published_rules" / f"{kind}_results.csv"
    if stored.exists():
        log(f"using stored R results {stored.name} (threshr 1.0.8, eva 0.2.7)")
        return pd.read_csv(stored)
    return None


def find_rscript():
    """Rscript on the PATH, or the newest standard Windows installation of R."""
    import glob
    import shutil
    exe = shutil.which("Rscript")
    if exe:
        return exe
    hits = sorted(glob.glob(r"C:\Program Files\R\R-*\bin\Rscript.exe"))
    return hits[-1] if hits else None


def run_r_benchmarks(kind="stress", nparts=1):
    """Export the samples and run the R benchmark script with Rscript (if R is installed)."""
    import shutil
    import subprocess
    rscript = find_rscript()
    if rscript is None:
        log("Rscript not found - using stored R results (data/published_rules/) if present")
        return load_rcomp(kind)
    folder = {"stress": export_rcomp_samples, "danish": export_danish_samples,
              "norwegian": export_norwegian_samples, "norfire_real": export_norfire_real_samples}[kind]()
    out = cache_dir() / {"stress": "rcomp_out", "danish": "rcomp_danish_out", "norwegian": "rcomp_norwegian_out",
                           "norfire_real": "rcomp_norfire_real_out"}[kind]
    out.mkdir(parents=True, exist_ok=True)
    script = R_SCRIPT
    procs = []
    for part in range(nparts):
        f = out / f"part{part}.csv"
        if not f.exists():
            logf = open(out / f"R_log_part{part}.txt", "w")
            procs.append((subprocess.Popen([rscript, str(script), str(folder), str(f), str(part), str(nparts)],
                                           stdout=logf, stderr=subprocess.STDOUT), logf))
    for p, logf in procs:
        p.wait()
        logf.close()
        if p.returncode != 0:
            warn(f"Rscript exited with code {p.returncode}; see {logf.name}")
    return load_rcomp(kind)

# ==========================================================================================
# ACCURACY TABLES FOR THE WEIGHTING SCHEMES
# ==========================================================================================
"""Accuracy tables for the threshold-weighting schemes, computed from the cached results.

All accuracy statistics use relative errors e = estimate / truth - 1 after the fallback rules
of `estimators.fill_fallbacks` (TPW/TMV -> TPW-core -> equal weights):
    RMSE (cells)   mean over design x n cells of sqrt(mean e^2)      RMSE (pooled) over all samples
    MAE            median |e|          Bias   median e
    Under / Over   shares of e < -20% and e > +100%
    Shortfall / Excess   mean max(-e, 0) and mean max(e, 0)  (under-/over-capitalization)
"""
import numpy as np
import pandas as pd


SIM_METHODS = ["single", "ew", "naive", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv", "tpw_uh", "tpw_uhd"]
MEAS_LABELS = {"var0.975": "VaR 97.5%", "var0.99": "VaR 99%", "var0.995": "VaR 99.5%", "var0.999": "VaR 99.9%",
               "es0.975": "ES 97.5%", "es0.99": "ES 99%"}


def prepare(d):
    """Keep successful replications, apply fallbacks and add relative errors re_<m>_<meas>."""
    d = d[d["ok"].astype(bool)].copy()
    methods = [m for m in SIM_METHODS if f"{m}_{MEASURES[0]}" in d]
    d = fill_fallbacks(d, methods)
    re = pd.DataFrame({f"re_{m}_{meas}": d[f"{m}_{meas}"] / d[f"true_{meas}"] - 1
                       for meas in MEASURES for m in methods}, index=d.index)
    d = pd.concat([d, re], axis=1)
    d.attrs["methods"] = methods
    return d


def _rmse(e):
    return 100 * np.sqrt(np.nanmean(np.asarray(e, dtype=float) ** 2))


def accuracy(d, cell):
    """Long table: accuracy of every method for every measure ."""
    rows = []
    methods = d.attrs["methods"]
    for meas in MEASURES:
        per = {m: d.groupby(cell)[f"re_{m}_{meas}"].apply(_rmse) for m in methods}
        for m in methods:
            e = d[f"re_{m}_{meas}"]
            rows.append({"measure": meas, "method": m, "label": LABELS[m],
                         "rmse_cells": per[m].mean(), "rmse_pooled": _rmse(e),
                         "mae": 100 * np.nanmedian(e.abs()), "bias": 100 * np.nanmedian(e),
                         "under20": 100 * np.mean(e < -0.2), "over100": 100 * np.mean(e > 1),
                         "shortfall": 100 * np.nanmean(np.maximum(-e, 0)), "excess": 100 * np.nanmean(np.maximum(e, 0)),
                         "wins_vs_ew": int((per[m] < per["ew"]).sum()), "wins_vs_cv": int((per[m] < per["cv"]).sum()),
                         "no_estimate_pct": 100 * d[f"noest_{m}_{meas}"].mean(), "cells": len(per[m])})
    return pd.DataFrame(rows)


def cell_rmse(d, cell, meas, methods):
    return pd.DataFrame({m: d.groupby(cell)[f"re_{m}_{meas}"].apply(_rmse) for m in methods})


# ----------------------------------------------------------------------------------------
# Simulation tables
# ----------------------------------------------------------------------------------------
ACCURACY_ROWS = {"var0.99": ["ew", "cv", "vpw", "tpw"],
               "var0.999": ["ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv"],
               "es0.975": ["ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv"],
               "es0.99": ["ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv"]}


def weighting_accuracy_table(acc):
    rows = [acc[(acc.measure == k) & (acc.method == m)].iloc[0] for k, ms in ACCURACY_ROWS.items() for m in ms]
    t = pd.DataFrame(rows)[["measure", "label", "rmse_cells", "rmse_pooled", "mae", "under20", "over100", "wins_vs_ew"]]
    t["measure"] = t["measure"].map(MEAS_LABELS)
    return t.reset_index(drop=True)


def es975_by_design_table(d):
    t = cell_rmse(d[d["n"] == 250], "scenario", "es0.975", ["ew", "cv", "vpw", "tpw", "tmv"])
    t = t.loc[[s for s in DESIGNS if s in t.index]]
    t.index = [DESIGN_LABELS[s] for s in t.index]
    return t.rename(columns=LABELS)


def shortfall_excess_table(acc):
    rows = []
    for meas in ["var0.99", "var0.995", "var0.999", "es0.975", "es0.99"]:
        a = acc[acc.measure == meas].set_index("method")
        lam = (a.loc["ew", "excess"] - a.loc["tpw", "excess"]) / (a.loc["tpw", "shortfall"] - a.loc["ew", "shortfall"])
        rows.append({"target": MEAS_LABELS[meas],
                     **{f"shortfall_{m}": a.loc[m, "shortfall"] for m in ("ew", "tpw", "cv")},
                     **{f"excess_{m}": a.loc[m, "excess"] for m in ("ew", "tpw", "cv")},
                     "break_even_lambda": lam})
    return pd.DataFrame(rows)


def _failed(d, col):
    return d[col].fillna(0) < COLLAPSE_NEFF


def failure_rate_table(d):
    """Failure rates (%): collapse (N_eff < 2) or fallback, by design."""
    def rates(g):
        return pd.Series({"CV-BMA": 100 * (g["status_cv"] != "ok").mean(),
                          "CV-BMA LOO+floor": 100 * (g["status_cv_loo"] != "ok").mean(),
                          "VPW (VaR 99%)": 100 * _failed(g, "Neff_vpw").mean(),
                          "TPW (ES 97.5%)": 100 * _failed(g, "Neff_tpw_es0.975").mean(),
                          "TMV (ES 97.5%)": 100 * _failed(g, "Neff_tmv_es0.975").mean()})
    cols = ["status_cv", "status_cv_loo", "Neff_vpw", "Neff_tpw_es0.975", "Neff_tmv_es0.975"]
    t = d.groupby("scenario")[cols].apply(rates).loc[[s for s in DESIGNS if s in set(d.scenario)]]
    t.index = [DESIGN_LABELS[s] for s in t.index]
    t.loc["All designs"] = rates(d)
    return t


def reliability(d):
    """Numbers quoted in Sections 4.1 and 5.2."""
    out = {"samples": len(d),
           "naive_BMA_collapse_pct": 100 * (d["Neff_naive"] < COLLAPSE_NEFF).mean() if "Neff_naive" in d else np.nan,
           "CV_fail_pct": 100 * (d["status_cv"] != "ok").mean(),
           "CV_fallback_pct": 100 * (d["status_cv"] == "fallback").mean(),
           "CV_collapse_pct": 100 * (d["status_cv"] == "collapse").mean(),
           "CV_LOO_fail_pct": 100 * (d["status_cv_loo"] != "ok").mean(),
           "VPW_fail_pct": 100 * _failed(d, "Neff_vpw").mean(),
           "median_Neff_VPW": d["Neff_vpw"].median()}
    for meas in ("es0.975", "es0.99", "var0.999"):
        out[f"TPW_fail_pct_{meas}"] = 100 * _failed(d, f"Neff_tpw_{meas}").mean()
        out[f"TPW_median_Neff_{meas}"] = d[f"Neff_tpw_{meas}"].median()
        out[f"TMV_fail_pct_{meas}"] = 100 * _failed(d, f"Neff_tmv_{meas}").mean()
        out[f"TMV_median_shrinkage_{meas}"] = d[f"lam_{meas}"].median()
    blocked = d[d.scenario == "Regime blocked"].groupby("n")["status_cv"].apply(lambda s: 100 * (s != "ok").mean())
    out.update({f"CV_fail_pct_regime_blocked_n{n}": v for n, v in blocked.items()})
    return pd.Series(out)


def exact_gpd_es_table(g):
    es975 = cell_rmse(g, ["xi", "n"], "es0.975", ["ew", "cv", "vpw", "tpw_core", "tpw"]).add_prefix("ES97.5_")
    es99 = cell_rmse(g, ["xi", "n"], "es0.99", ["ew", "cv", "tpw"]).add_prefix("ES99_")
    return pd.concat([es975, es99], axis=1)


def bias_term_versions_table(acc_stress, acc_gpd):
    rows = []
    for m in ("tpw_core", "tpw_uh", "tpw_uhd", "tpw"):
        r = {"version": LABELS[m] if m != "tpw" else "Full-grid consensus, debiased (TPW)"}
        for name, acc in (("Stress", acc_stress), ("Exact GPD", acc_gpd)):
            for meas in ("es0.975", "es0.99"):
                a = acc[(acc.measure == meas) & (acc.method == m)]
                r[f"{name}: {MEAS_LABELS[meas]}"] = a["rmse_cells"].iloc[0] if len(a) else np.nan
        rows.append(r)
    return pd.DataFrame(rows)


def r_benchmark_table(stress, rc):
    """R benchmarks on the samples processed by R (600 in full mode): pooled RMSE, bias,
    over, under. Missing estimates (e.g. ForwardStop without a finite ES) -> equal weights."""
    mm = stress.merge(rc, on=["scenario", "n", "rep"], how="inner")
    rows = []
    for meas in ("var0.99", "var0.999", "es0.975", "es0.99"):
        for k in ("ew", "nbma", "nbest", "fstop", "cv", "vpw", "tpw"):
            v = mm[f"{k}_{meas}"]
            noest = 100 * v.isna().mean()
            e = v.fillna(mm[f"ew_{meas}"]) / mm[f"true_{meas}"] - 1
            rows.append({"target": MEAS_LABELS[meas], "scheme": LABELS[k], "rmse_pooled": _rmse(e),
                         "bias": 100 * np.nanmedian(e), "over100": 100 * np.mean(e > 1),
                         "under20": 100 * np.mean(e < -0.2), "no_estimate_pct": noest, "samples": len(mm)})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# Market data
# ----------------------------------------------------------------------------------------
SAMPLE_LABELS = {"S&P 500: full_sample": "S&P 500, full sample", "S&P 500: GFC": "S&P 500, financial crisis",
                 "S&P 500: COVID": "S&P 500, COVID year", "S&P 500: Inflation": "S&P 500, inflation",
                 **{f"Panel: {a}": n for a, n in ASSET_NAMES.items()}}


def market_levels_table(levels):
    t = levels[levels["sample"] != "Panel: SP500"].copy()
    for meas in MEASURES:
        for m in ("tpw", "tmv"):
            t[f"{m}_{meas}"] = t[f"{m}_{meas}"].fillna(t[f"tpw_core_{meas}"])
    cols = {"n": "n"}
    for meas in ("es0.975", "es0.99", "var0.999"):
        for m in ("ew", "cv", "tpw"):
            cols[f"{m}_{meas}"] = f"{MEAS_LABELS[meas]}: {LABELS[m]}"
    out = t.set_index("sample")[list(cols)].rename(columns=cols)
    out.index = pd.Index([SAMPLE_LABELS.get(s, s) for s in out.index], name="sample")
    out["CV-BMA status"] = t["status_cv"].values
    for meas in ("es0.99", "var0.999"):
        out[f"{MEAS_LABELS[meas]}: single threshold"] = t[f"single_{meas}"].values
        out[f"{MEAS_LABELS[meas]}: range across thresholds (% of mean)"] = t[f"range_{meas}"].values
    return out


WIN_METHODS = ["ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw"]


def window_matrix(df, meas):
    M = df[[f"{m}_{meas}" for m in WIN_METHODS]].copy()
    M.columns = WIN_METHODS
    M["tpw"] = M["tpw"].fillna(M["tpw_core"])
    return M.apply(lambda c: c.fillna(M["ew"]))          # no estimate -> equal weights


def stressed_windows_table(windows, meas="es0.99"):
    """Month-to-month stability on rolling 250-day windows, by series. The last row averages
    the series (mean absolute change, level gap and CV failure share) and sums the counts."""
    rows = []
    for name, df in windows.items():
        M = window_matrix(df, meas)
        r = {"series": SAMPLE_LABELS.get(f"Panel: {name}", name), "windows": len(M)}
        for m in ("ew", "cv", "tpw"):
            ch = 100 * M[m].pct_change(fill_method=None).abs().dropna()
            r[f"mean_abs_change_{m}"] = ch.mean()
            r[f"changes_over_25pct_{m}"] = int((ch > 25).sum())
        r["tpw_vs_ew_level_pct"] = 100 * (M["tpw"] / M["ew"] - 1).mean()
        r["cv_fails_pct"] = 100 * (df["status_cv"] != "ok").mean()
        r["cv_fails"] = int((df["status_cv"] != "ok").sum())
        r["cv_loo_fails"] = int((df["status_cv_loo"] != "ok").sum())
        rows.append(r)
    t = pd.DataFrame(rows)
    allr = {"series": "All series", "windows": int(t["windows"].sum())}
    for m in ("ew", "cv", "tpw"):
        allr[f"mean_abs_change_{m}"] = t[f"mean_abs_change_{m}"].mean()
        allr[f"changes_over_25pct_{m}"] = int(t[f"changes_over_25pct_{m}"].sum())
    allr["tpw_vs_ew_level_pct"] = t["tpw_vs_ew_level_pct"].mean()
    allr["cv_fails"] = int(t["cv_fails"].sum())
    allr["cv_fails_pct"] = 100 * allr["cv_fails"] / max(allr["windows"], 1)
    allr["cv_loo_fails"] = int(t["cv_loo_fails"].sum())
    return pd.concat([t, pd.DataFrame([allr])], ignore_index=True)


def largest_disagreements(windows, meas="es0.975", top=3):
    rows = []
    for name, df in windows.items():
        M = window_matrix(df, meas)
        spread = M[["ew", "cv", "tpw"]].max(axis=1) / M[["ew", "cv", "tpw"]].min(axis=1)
        for end in spread.sort_values(ascending=False).index[:top]:
            rows.append({"series": name, "window_end": str(pd.Timestamp(end).date()), "max/min": spread[end],
                         **{LABELS[m]: M.loc[end, m] for m in ("ew", "cv", "tpw")},
                         "CV-BMA status": df.loc[end, "status_cv"]})
    return pd.DataFrame(rows)


BT_LABELS = ["ew", "cv", "vpw", "tpw_core", "tpw"]


def backtest_summary_table(bt, dm):
    rows = []
    for a in sorted(bt.level.unique()):
        for m in BT_LABELS:
            b = bt[(bt.level == a) & (bt.method == m)]
            d_ew = dm[(dm.level == a) & (dm.A == m) & (dm.B == "ew")]
            d_cv = dm[(dm.level == a) & (dm.A == m) & (dm.B == "cv")]
            rows.append({"level": a, "scheme": LABELS[m], "series": len(b), "mean_FZ0": b["FZ0"].mean(),
                         "Z2_not_green": int((b["Z2_zone"] != "GREEN").sum()),
                         "blocks_yellow_or_red": int((b["blocks_yellow"] + b["blocks_red"]).sum()),
                         "blocks": int(b["blocks"].sum()),
                         "MF_reject": int((b["MF_p"] < 0.05).sum()), "CC_reject": int((b["cc_p"] < 0.05).sum()),
                         "mean_ES": b["mean_ES"].mean(),
                         "DM_vs_EW (better/worse)": "–" if m == "ew" else f"{int((d_ew.better == m).sum())}/{int((d_ew.better == 'ew').sum())}",
                         "DM_vs_CV (better/worse)": "–" if m == "cv" else f"{int((d_cv.better == m).sum())}/{int((d_cv.better == 'cv').sum())}"})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# Danish fire losses
# ----------------------------------------------------------------------------------------
DAN_METHODS = ["ew", "cv", "vpw", "tpw", "median", "screen"]


def _danish_filled(dan):
    t = dan.copy()
    for meas in MEASURES:
        t[f"tpw_{meas}"] = t[f"tpw_{meas}"].fillna(t[f"tpw_core_{meas}"])
    return t


def danish_stability_table(dan, rc=None):
    t = _danish_filled(dan)
    full, yr = t.iloc[0], t.iloc[1:]
    if rc is not None:
        rc = rc.sort_values("rep")
        full = pd.concat([full, rc[rc.rep == 0].iloc[0][[c for c in rc if c.startswith("nbma_")]]])
    rows = []
    for meas, stat_list in [("var0.995", ["full", "medlog", "maxratio"]), ("var0.999", ["full", "maxratio", "over2"]),
                        ("es0.975", ["full", "maxratio"]), ("es0.99", ["full", "medlog", "maxratio"])]:
        for st in stat_list:
            r = {"measure": MEAS_LABELS[meas], "statistic": {"full": "Full sample", "medlog": "Annual: median abs. log dev.",
                                                            "maxratio": "Annual: largest ratio", "over2": "Annual: years above 2x"}[st]}
            for m in DAN_METHODS:
                v = yr[f"{m}_{meas}"].fillna(yr[f"ew_{meas}"])
                ld = np.log(v / full[f"{m}_{meas}"])
                r[LABELS[m]] = {"full": full[f"{m}_{meas}"], "medlog": float(np.median(np.abs(ld))),
                                "maxratio": float(np.exp(ld.max())), "over2": int((ld > np.log(2)).sum())}[st]
            if rc is not None:
                ry = rc[rc.rep != 0].set_index("rep")[f"nbma_{meas}"]
                ld = np.log(ry / full[f"nbma_{meas}"])
                r[LABELS["nbma"]] = {"full": full[f"nbma_{meas}"], "medlog": np.nan,
                                     "maxratio": float(np.exp(np.nanmax(ld))) if meas == "es0.99" else np.nan,
                                     "over2": np.nan}[st]
            rows.append(r)
    return pd.DataFrame(rows)


def danish_by_year_table(dan):
    t = _danish_filled(dan).iloc[1:]
    out = pd.DataFrame({"Year": t["sample"].values, "Claims": t["n"].values, "CV-BMA status": t["status_cv"].values})
    for m in DAN_METHODS:
        out[LABELS[m]] = t[f"{m}_es0.99"].values
    return out


# ----------------------------------------------------------------------------------------
# Norwegian fire claims (annual samples; nominal 1000 NOK, so no pooled long-run value)
# ----------------------------------------------------------------------------------------
NOR_METHODS = ["ew", "cv", "vpw", "tpw_core", "tpw", "median", "trim20", "screen"]


def _nor_filled(nor):
    t = nor.copy()
    for meas in MEASURES:
        t[f"tpw_{meas}"] = t[f"tpw_{meas}"].fillna(t[f"tpw_core_{meas}"])
        for m in NOR_METHODS:
            t[f"{m}_{meas}"] = t[f"{m}_{meas}"].fillna(t[f"ew_{meas}"])
    return t


def table_norwegian(nor, rc=None):
    """Year-to-year stability of annual estimates: median absolute log change between
    consecutive years, largest year-to-year ratio, number of changes by more than a factor of
    two, and the ratio of the largest to the smallest annual estimate."""
    t = _nor_filled(nor).sort_values("sample")
    if rc is not None:
        rc = rc.sort_values("rep")
    rows = []
    for meas in ("var0.995", "var0.999", "es0.975", "es0.99"):
        methods = NOR_METHODS + (["nbma"] if rc is not None else [])
        for m in methods:
            v = (rc.set_index("rep")[f"nbma_{meas}"].reindex(t["sample"].astype(int)).values
                 if m == "nbma" else t[f"{m}_{meas}"].values)
            lc = np.diff(np.log(v))
            rows.append({"measure": MEAS_LABELS[meas], "scheme": LABELS[m],
                         "median_abs_log_change": float(np.nanmedian(np.abs(lc))),
                         "largest_yoy_ratio": float(np.exp(np.nanmax(np.abs(lc)))),
                         "changes_over_2x": int(np.nansum(np.abs(lc) > np.log(2))),
                         "max_over_min": float(np.nanmax(v) / np.nanmin(v))})
    return pd.DataFrame(rows)


def table_norwegian_by_year(nor):
    t = _nor_filled(nor).sort_values("sample")
    out = pd.DataFrame({"Year": t["sample"].values, "Claims": t["n"].values,
                        "Largest fitted shape": t["xi_max"].values})
    for m in ("ew", "cv", "vpw", "tpw", "median", "screen"):
        out[LABELS[m]] = t[f"{m}_es0.99"].values
    return out

# ==========================================================================================
# TABLES FOR THE PROTECTIONS
# ==========================================================================================
"""Tables for the family of protections against near-singular ES estimates, all computed
from cached results.

Methods compared (column prefixes): equal weights (ew), CV-BMA (cv), VPW (vpw), median across
thresholds (median), screened equal weights (screen), capped shape (cap, xi <= 0.8), Coles-Dixon
penalised likelihood (pen), reduced-bias Hill / Weissman (chw), TPW (tpw).
The TPW-median gap |log(TPW / median)| of the 99% ES is one of the reliability checks.
"""
import numpy as np
import pandas as pd


PROTECT = [("ew", "Equal weights"), ("cv", "CV-BMA"), ("vpw", "VPW"), ("median", "Median"),
           ("screen", "Screened EW"), ("cap", "Capped shape"), ("pen", "Penalised"),
           ("chw", "Bias-reduced Hill"), ("tpw", "TPW")]
FAMILY = [p for p in PROTECT if p[0] not in ("cv", "vpw")]
MEAS_NAMES = {"var0.995": "VaR 99.5%", "var0.999": "VaR 99.9%", "es0.975": "ES 97.5%", "es0.99": "ES 99%"}
GAP_BINS = (0.10, 0.25)                         # TPW-median gap classes: < 10%, 10-25%, > 25%
FLAG_XI = 0.9                                   # a sample is "flagged" if some fitted shape >= 0.9


def prepare_stress(stress, combiners, extra):
    """One frame per simulated sample: main results (fallbacks applied), robust combiners and
    the extra benchmarks. `xi_max` is the largest fitted shape (MLE) on the grid."""
    keep = [c for c in stress if not c.startswith(("median_", "trim20_", "screen_"))]
    comb = combiners.drop(columns=[c for c in combiners if c.startswith("true_") or c == "ok"])
    ex = extra.drop(columns=[c for c in extra if c.startswith("true_")])
    d = stress[keep].merge(comb, on=["scenario", "n", "rep"]).merge(ex, on=["scenario", "n", "rep"])
    if "xi_max" not in d and "mle_xi_max" in d:
        d["xi_max"] = d["mle_xi_max"]
    return d


def _err(d, m, meas):
    return d[f"{m}_{meas}"].fillna(d[f"ew_{meas}"]) / d[f"true_{meas}"] - 1


def _cell_rmse(d, m, meas, log=False, by=("scenario", "n")):
    e = _err(d, m, meas)
    if log:
        e = np.log1p(e)
    return float(e.groupby([d[b] for b in by]).apply(lambda z: 100 * np.sqrt(np.nanmean(z ** 2))).mean())


def table_protection(d, measures=("es0.975", "es0.99", "var0.995", "var0.999"), methods=PROTECT):
    """Cell-averaged relative RMSE, RMSE of the log ratio, and the shares of samples with an
    underestimate by more than 20% and an overestimate by more than 50% (all in %)."""
    rows = []
    for meas in measures:
        for stat, f in (("Relative RMSE", lambda m: _cell_rmse(d, m, meas)),
                        ("RMSE of log ratio", lambda m: _cell_rmse(d, m, meas, log=True)),
                        ("Share too low by > 20%", lambda m: 100 * float((_err(d, m, meas) < -0.2).mean())),
                        ("Share too high by > 50%", lambda m: 100 * float((_err(d, m, meas) > 0.5).mean()))):
            rows.append({"measure": MEAS_NAMES[meas], "statistic": stat, **{lab: f(m) for m, lab in methods}})
    return pd.DataFrame(rows)


def table_by_design(d, meas="es0.99", methods=FAMILY):
    """For each design: share of samples with a fitted shape >= 0.9, and relative RMSE (median
    relative error) of each method, averaged over the sample sizes."""
    rows = []
    for s, g in d.groupby("scenario", sort=False):
        r = {"design": s, "flagged_%": 100 * float((g["xi_max"] >= FLAG_XI).mean())}
        for m, lab in methods:
            r[f"{lab} RMSE"] = _cell_rmse(g, m, meas, by=("n",))
            r[f"{lab} median error"] = 100 * float(np.nanmedian(_err(g, m, meas)))
        rows.append(r)
    return pd.DataFrame(rows)


def table_ordinary(d, measures=("es0.975", "es0.99", "var0.999"), methods=FAMILY):
    """Cell-averaged relative RMSE in samples without a near-singular fit (all fitted shapes
    below 0.9) and in the others."""
    rows = []
    for label, g in (("No fitted shape >= 0.9", d[d["xi_max"] < FLAG_XI]),
                     ("Some fitted shape >= 0.9", d[d["xi_max"] >= FLAG_XI])):
        for meas in measures:
            rows.append({"samples": label, "n_samples": len(g), "measure": MEAS_NAMES[meas],
                         **{lab: _cell_rmse(g, m, meas) for m, lab in methods}})
    return pd.DataFrame(rows)


def gap(d, meas="es0.99"):
    t = d[f"tpw_{meas}"].fillna(d[f"tpw_core_{meas}"]) if f"tpw_core_{meas}" in d else d[f"tpw_{meas}"]
    return np.abs(np.log(t / d[f"median_{meas}"]))


def table_gap(d, meas="es0.99", methods=FAMILY):
    """Samples grouped by the TPW-median gap: share of samples, share with a fitted shape
    >= 0.9, pooled relative RMSE of each method and the share of TPW errors above 50%."""
    g = gap(d, meas)
    lo, hi = np.log1p(GAP_BINS[0]), np.log1p(GAP_BINS[1])
    cls = pd.cut(g, [-np.inf, lo, hi, np.inf], labels=["below 10%", "10% to 25%", "above 25%"])
    rows = []
    for c, gg in d.groupby(cls, observed=False):
        e = {m: _err(gg, m, meas) for m, _ in methods}
        rows.append({"gap": c, "samples_%": 100 * len(gg) / len(d), "flagged_%": 100 * float((gg["xi_max"] >= FLAG_XI).mean()),
                     **{lab: 100 * float(np.sqrt(np.nanmean(e[m] ** 2))) for m, lab in methods},
                     "TPW |error| > 50% (%)": 100 * float((np.abs(e["tpw"]) > 0.5).mean())})
    return pd.DataFrame(rows)


def table_caps(d, measures=("es0.975", "es0.99", "var0.999")):
    caps = [("cap70", "xi <= 0.7"), ("cap", "xi <= 0.8"), ("cap90", "xi <= 0.9")]
    rows = []
    for meas in measures:
        rows.append({"measure": MEAS_NAMES[meas], "statistic": "Relative RMSE", **{lab: _cell_rmse(d, m, meas) for m, lab in caps}})
        rows.append({"measure": MEAS_NAMES[meas], "statistic": "Share too low by > 20%",
                     **{lab: 100 * float((_err(d, m, meas) < -0.2).mean()) for m, lab in caps}})
    return pd.DataFrame(rows)


def table_gpd(g, meas="es0.99", methods=FAMILY):
    """Exact GPD samples: relative RMSE and median relative error by shape and sample size."""
    rows = []
    for (xi, n), gg in g.groupby(["xi", "n"]):
        r = {"xi": xi, "n": n}
        for m, lab in methods:
            e = _err(gg, m, meas)
            r[f"{lab} RMSE"] = 100 * float(np.sqrt(np.nanmean(e ** 2)))
            r[f"{lab} median error"] = 100 * float(np.nanmedian(e))
        rows.append(r)
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# Loss data: full sample and annual samples (Danish losses, Norwegian claims at 2012 prices)
# ----------------------------------------------------------------------------------------
def real_frame(main, extra, kind):
    t = main.copy()
    t["sample"] = t["sample"].astype(str)
    ex = extra[extra["kind"] == kind].drop(columns=["kind", "n"]).copy()
    ex["sample"] = ex["sample"].astype(str)
    t = t.drop(columns=[c for c in t if c.startswith(("cap", "pen_", "chw_"))]).merge(ex, on="sample", how="left")
    for meas in MEASURES:
        t[f"tpw_{meas}"] = t[f"tpw_{meas}"].fillna(t[f"tpw_core_{meas}"])
    return t


def empirical_es(x, a):
    """Mean of the ceil(n (1 - a)) largest observations: a crude nonparametric ES."""
    x = np.sort(np.asarray(x, dtype=float))[::-1]
    return float(x[: max(1, int(np.ceil(len(x) * (1 - a) - 1e-9)))].mean())


def add_empirical(t, samples):
    """Add the empirical ES at 97.5% and 99% and the largest loss of each sample (samples:
    dict name -> losses)."""
    t = t.copy()
    for a in (0.975, 0.99):
        t[f"emp_es{a}"] = [empirical_es(samples[s], a) for s in t["sample"]]
    t["largest"] = [float(np.max(samples[s])) for s in t["sample"]]
    return t


def table_real(t, rc=None, methods=PROTECT):
    """Full-sample estimate, and for the annual samples the median absolute log deviation from
    it, the largest and smallest ratio to it and the number of years above twice it.
    Row 0 of t is the full sample; rc (optional) holds the Bayesian benchmark (nbma_)."""
    full, yr = t.iloc[0], t.iloc[1:]
    if rc is not None:
        rc = rc.sort_values("rep")
        rfull, ryr = rc[rc.rep == 0].iloc[0], rc[rc.rep != 0]
    rows = []
    for meas in ("var0.995", "var0.999", "es0.975", "es0.99"):
        for st, lab in (("full", "Full sample"), ("medlog", "Annual: median abs. log deviation"),
                        ("maxratio", "Annual: largest ratio"), ("minratio", "Annual: smallest ratio"),
                        ("over2", "Annual: years above 2x"), ("belowemp", "Annual: years below empirical ES")):
            if st == "belowemp" and (not meas.startswith("es") or f"emp_{meas}" not in t):
                continue
            r = {"measure": MEAS_NAMES[meas], "statistic": lab}
            cols = list(methods) + ([("nbma", "Bayesian (Northrop et al.)")] if rc is not None else [])
            for m, name in cols:
                if m == "nbma":
                    f, v = rfull[f"nbma_{meas}"], ryr.set_index("rep")[f"nbma_{meas}"].reindex(yr["sample"].astype(int)).values
                else:
                    f, v = full[f"{m}_{meas}"], yr[f"{m}_{meas}"].fillna(yr[f"ew_{meas}"]).values
                ld = np.log(np.asarray(v, dtype=float) / f)
                below = (int(np.nansum(np.asarray(v, dtype=float) < yr[f"emp_{meas}"].values))
                         if st == "belowemp" else None)
                r[name] = {"full": f, "medlog": np.nanmedian(np.abs(ld)), "maxratio": np.exp(np.nanmax(ld)),
                           "minratio": np.exp(np.nanmin(ld)), "over2": int(np.nansum(ld > np.log(2))),
                           "belowemp": below}[st]
            rows.append(r)
    return pd.DataFrame(rows)


def table_real_by_year(t, meas="es0.99"):
    out = pd.DataFrame({"sample": t["sample"].values, "claims": t["n"].values,
                        "largest fitted shape": t["xi_max"].values,
                        "largest claim": t["largest"].values if "largest" in t else np.nan,
                        "empirical ES 99%": t["emp_es0.99"].values if "emp_es0.99" in t else np.nan,
                        "TPW-median gap (%)": 100 * (np.exp(gap(t, meas).values) - 1)})
    for m, lab in PROTECT:
        out[lab] = t[f"{m}_{meas}"].fillna(t[f"ew_{meas}"]).values
    return out


# ----------------------------------------------------------------------------------------
# Capital view: asymmetric cost of under- and over-capitalization
# ----------------------------------------------------------------------------------------
LAMBDAS = (1, 2, 5, 10)


def capital_terms(d, m, meas, by=("scenario", "n")):
    """Cell-averaged mean relative shortfall E max(1 - est/true, 0) and excess E max(est/true - 1, 0), in %."""
    e = _err(d, m, meas)
    g = [d[b] for b in by]
    sh = (100 * np.maximum(-e, 0)).groupby(g).mean().mean()
    ex = (100 * np.maximum(e, 0)).groupby(g).mean().mean()
    return float(sh), float(ex)


def table_capital(d, measures=("es0.975", "es0.99", "var0.995", "var0.999"), methods=FAMILY, lambdas=LAMBDAS):
    """Capital set equal to the estimate: mean shortfall and excess (% of the true capital), and the
    expected cost lambda * shortfall + excess for several cost ratios lambda."""
    rows = []
    for meas in measures:
        for m, lab in methods:
            sh, ex = capital_terms(d, m, meas)
            rows.append({"measure": MEAS_NAMES[meas], "method": lab, "shortfall": sh, "excess": ex,
                         **{f"cost_lambda{l}": l * sh + ex for l in lambdas}})
    return pd.DataFrame(rows)


def break_even(d, a, b, meas):
    """Cost ratio lambda at which methods a and b have equal expected cost (nan if one dominates)."""
    sa, ea = capital_terms(d, a, meas)
    sb, eb = capital_terms(d, b, meas)
    if (sa - sb) == 0:
        return np.nan
    lam = (eb - ea) / (sa - sb)
    return float(lam) if lam > 0 else np.nan


def table_regret(d, measures=("es0.975", "es0.99", "var0.995", "var0.999"), methods=FAMILY, lambdas=(1, 2, 3, 5, 10, 20)):
    """Expected capital cost relative to the best method at the same cost ratio (1 = best), and the
    worst ratio over the cost ratios (maximum regret)."""
    rows = []
    for meas in measures:
        terms = {lab: capital_terms(d, m, meas) for m, lab in methods}
        best = {l: min(l * s + e for s, e in terms.values()) for l in lambdas}
        for lab, (s, e) in terms.items():
            r = {l: (l * s + e) / best[l] for l in lambdas}
            rows.append({"measure": MEAS_NAMES[meas], "method": lab, **{f"lambda{l}": r[l] for l in lambdas},
                         "max_regret": max(r.values())})
    return pd.DataFrame(rows)


CONSERVATIVE = ["median", "screen", "cap", "tpw"]


def table_capital_range(t, meas="es0.99"):
    """Model risk in capital terms: ratio of the largest to the smallest estimate across methods,
    full sample and median / maximum over the annual samples (row 0 of t is the full sample)."""
    def ratio(cols):
        v = np.column_stack([t[f"{m}_{meas}"].fillna(t[f"ew_{meas}"]).values for m in cols])
        return np.nanmax(v, axis=1) / np.nanmin(v, axis=1)
    rows = []
    for lab, cols in (("Median, screened EW, capped shape, TPW", CONSERVATIVE),
                      ("... and penalized likelihood", CONSERVATIVE + ["pen"]),
                      ("All six protections", CONSERVATIVE + ["pen", "chw"]),
                      ("Equal weights, CV-BMA, VPW (unprotected)", ["ew", "cv", "vpw"])):
        r = ratio(cols)
        rows.append({"methods": lab, "full_sample": r[0], "annual_median": float(np.median(r[1:])), "annual_max": float(np.max(r[1:]))})
    return pd.DataFrame(rows)

# ==========================================================================================
# NEAR-SINGULAR FITS AND THE NUMBER OF EXCEEDANCES
# ==========================================================================================
"""Near-singular fits as a function of sample information: probability that the fitted
GPD shape reaches xi* as a function of the number of exceedances k, for GPD and non-GPD tails,
by simulation, against the normal approximation."""
import numpy as np
import pandas as pd
from scipy import stats


KS = (10, 15, 20, 30, 40, 60, 80, 100, 150, 200)
XI_STARS = (0.8, 0.9, 0.95)
TAILS = {                       # name -> (tail index xi of the law, sampler(n, rng))
    "GPD, xi = 0.2": (0.2, lambda n, r: stats.genpareto.rvs(0.2, size=n, random_state=r)),
    "GPD, xi = 0.5": (0.5, lambda n, r: stats.genpareto.rvs(0.5, size=n, random_state=r)),
    "Student-t, 3 df": (1 / 3, lambda n, r: r.standard_t(3, n)),
    "Student-t, 5 df": (0.2, lambda n, r: r.standard_t(5, n)),
    "Regime mixture": (0.25, lambda n, r: np.where(r.random(n) < 0.8, r.standard_normal(n), 3 * r.standard_t(4, n))),
}
EXCEED = 0.05                   # non-GPD tails: threshold at the 95% quantile, n = k / 0.05


def _cell(tail, k, R):
    xi0, sampler = TAILS[tail]
    rng = stream("PROP4", tail, k)
    shapes = np.full(R, np.nan)
    gpd = tail.startswith("GPD")
    for r in range(R):
        if gpd:
            y = sampler(k, rng)
        else:
            x = sampler(int(round(k / EXCEED)), rng)
            u = np.sort(x)[-(k + 1)]
            y = x[x > u] - u
        f = fit_gpd(y)
        if f.ok:
            shapes[r] = f.xi
    out = {"tail": tail, "xi": xi0, "k": k, "R": R, "fits_ok": int(np.isfinite(shapes).sum())}
    for xs in XI_STARS:
        out[f"sim_{xs}"] = float(np.nanmean(shapes >= xs)) if np.isfinite(shapes).any() else np.nan
        out[f"normal_{xs}"] = float(stats.norm.sf(np.sqrt(k) * (xs - xi0) / (1 + xi0)))
    return out


def run_near_singular_k(R=10000):
    jobs = [(t, k, R) for t in TAILS for k in KS]
    return pd.DataFrame(pmap(_cell, jobs))


def slopes(df, xi_star, kmin=15):
    """Slope of log P(xi_hat >= xi*) on k (simulated and normal), over k >= kmin with P > 0."""
    rows = []
    for t, g in df.groupby("tail", sort=False):
        g = g[(g.k >= kmin) & (g[f"sim_{xi_star}"] > 0)]
        if len(g) < 3:
            rows.append({"tail": t, "xi_star": xi_star, "slope_sim": np.nan, "slope_normal": np.nan, "k_range": ""})
            continue
        s1 = np.polyfit(g.k, np.log(g[f"sim_{xi_star}"]), 1)[0]
        s2 = np.polyfit(g.k, np.log(g[f"normal_{xi_star}"]), 1)[0]
        rows.append({"tail": t, "xi_star": xi_star, "slope_sim": s1, "slope_normal": s2,
                     "k_range": f"{int(g.k.min())}-{int(g.k.max())}"})
    return pd.DataFrame(rows)


# ==========================================================================================
# RUN TIMES
# ==========================================================================================
"""Run times of the methods: seconds per sample on one core."""
import time

import numpy as np
import pandas as pd



def _t(f, reps):
    out = []
    for _ in range(reps):
        t0 = time.perf_counter(); f(); out.append(time.perf_counter() - t0)
    return float(np.median(out))


def run_timing(ns=(250, 1000, 5000), B=100, reps=5, design="Student-t3"):
    rows = []
    for n in ns:
        x = simulate(design, n, 0)
        u = np.quantile(x, QS)
        est, fits = per_threshold(x, u, return_fits=True)
        rows.append({"n": n, "method": "Equal weights, median, screened EW (13 ML fits)", "seconds": _t(lambda: per_threshold(x, u), reps)})
        rows.append({"n": n, "method": "Capped shape", "seconds": _t(lambda: per_threshold_fitter(x, u, fit_gpd_capped), reps)})
        rows.append({"n": n, "method": "Penalized likelihood", "seconds": _t(lambda: per_threshold_fitter(x, u, fit_gpd_penalised), reps)})
        rows.append({"n": n, "method": "Bias-reduced Hill", "seconds": _t(lambda: per_threshold_chw(x, u), reps)})
        rows.append({"n": n, "method": "CV-BMA (5 blocked folds)", "seconds": _t(lambda: cv_bma_kfold(x, u, fits, K=5, floor=False), reps)})

        def tpw():
            reps_ = bootstrap_reps(x, u, B, stream("TIMING", n))
            return [tpw_weights(reps_[:, :, k], est[:, k]) for k in range(est.shape[1])]
        rows.append({"n": n, "method": f"TPW (B = {B}, all six targets)", "seconds": _t(tpw, max(1, reps // 2))})
    return pd.DataFrame(rows)


# ==========================================================================================
# SHAPE POOLING
# ==========================================================================================
"""Shape-pooled POT.

Under the GPD the shape is the same above every threshold (threshold stability), but the usual
POT fit estimates it separately at each threshold, and the top thresholds, with few exceedances,
produce the near-singular shapes that make ES explode. Shape pooling estimates one shape from all
thresholds and refits only the scale at each threshold:

SP    pooled shape = TPW weights applied to the per-threshold shape
      estimates, with bootstrap replicates from the same resamples as the main study.
SP-k  pooled shape = exceedance-weighted mean of the shape estimates (no bootstrap).

Then VaR and ES at each threshold from (pooled shape, scale refitted with that shape), averaged
over the thresholds with equal weights.
"""
import math

import numpy as np
from scipy.optimize import minimize_scalar



def _sp_nll(xi, lb, y):
    beta = math.exp(lb)
    if abs(xi) < 1e-8:
        return y.size * lb + y.sum() / beta
    t = xi * y / beta
    if np.any(t <= -1):
        return math.inf
    return y.size * lb + (1.0 + 1.0 / xi) * np.log1p(t).sum()


def scale_given_shape(y, xi):
    """Maximum likelihood scale of the GPD for the excesses y with the shape fixed at xi."""
    y = np.asarray(y, dtype=float)
    if xi < 0:                                   # support: beta > -xi * max(y)
        lo = math.log(-xi * y.max() * (1 + 1e-9))
    else:
        lo = math.log(max(y.mean() * max(1 - xi, 0.05), 1e-12)) - 8
    hi = math.log(max(y.mean(), 1e-12)) + 8
    if lo >= hi:
        hi = lo + 8
    r = minimize_scalar(lambda lb: _sp_nll(xi, lb, y), bounds=(lo, hi), method="bounded", options={"xatol": 1e-10})
    return math.exp(r.x)


def _sp_shapes(x, u):
    out = np.full(len(u), np.nan)
    for j, v in enumerate(u):
        f = fit_gpd(x[x > v] - v)
        if f.ok:
            out[j] = f.xi
    return out


def pooled_estimates(x, u, xi_bar):
    """VaR / ES at each threshold with the shape fixed at xi_bar; M x K matrix."""
    n = x.size
    est = np.full((len(u), len(MEASURES)), np.nan)
    if not np.isfinite(xi_bar):
        return est
    for j, v in enumerate(u):
        y = x[x > v] - v
        if y.size < 5:
            continue
        f = GPDFit(float(xi_bar), scale_given_shape(y, xi_bar), np.nan, y.size, True)
        p = y.size / n
        est[j] = [pot_var(v, f, p, a) for a in VAR_LEVELS] + [pot_es(v, f, p, a) for a in ES_LEVELS]
    return est


def shape_pooled(x, rng, B, qs=QS):
    """SP and SP-k for one sample. rng must be the bootstrap stream of the main study (the
    resamples are drawn exactly as in estimators.bootstrap_reps)."""
    import warnings
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    n = x.size
    u = np.quantile(x, qs)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        xi = _sp_shapes(x, u)
        reps = np.full((B, len(u)), np.nan)
        for b in range(B):
            reps[b] = _sp_shapes(x[rng.integers(0, n, n)], u)
        w = tpw_weights(reps, xi)
        ok = np.isfinite(xi) & np.isfinite(w)
        xi_sp = float(np.sum(w[ok] * xi[ok]) / np.sum(w[ok])) if ok.any() and np.sum(w[ok]) > 0 else np.nan
        k = np.array([(x > v).sum() for v in u], dtype=float)
        okk = np.isfinite(xi)
        xi_spk = float(np.sum(k[okk] * xi[okk]) / k[okk].sum()) if okk.any() else np.nan
        out = {"sp_xi": xi_sp, "spk_xi": xi_spk}
        for name, xb in (("sp", xi_sp), ("spk", xi_spk)):
            est = pooled_estimates(x, u, xb)
            for m, meas in enumerate(MEASURES):
                e = est[:, m]
                out[f"{name}_{meas}"] = float(np.nanmean(e)) if np.isfinite(e).any() else np.nan
    return out


