# ==========================================================================================
# RELIABILITY CHECKS, ADDITIONAL DESIGNS AND DATA, IDENTIFICATION
# ==========================================================================================
"""Reliability checks (TPW-median gap, z-gap, shape bound), bootstrap intervals, additional
simulation designs, additional loss data sets, out-of-sample scoring, dynamic forecasts,
sensitivity of the fixed constants and the identification analysis."""
import math
import warnings

import numpy as np
import pandas as pd
from scipy import integrate, stats


J_MID = int(np.argmin(np.abs(QS - 0.91)))       # middle threshold of the grid (q = 0.91)
TARGETS = ("es0.975", "es0.99")


# ----------------------------------------------------------------------------------------
# A-C. Diagnostics from one bootstrap
# ----------------------------------------------------------------------------------------
def _fit_all(x, u):
    n = x.size
    est = np.full((len(u), len(MEASURES)), np.nan)
    xi = np.full(len(u), np.nan)
    for j, v in enumerate(u):
        y = x[x > v] - v
        f = fit_gpd(y)
        if f.ok:
            p = y.size / n
            est[j] = [pot_var(v, f, p, a) for a in VAR_LEVELS] + [pot_es(v, f, p, a) for a in ES_LEVELS]
            xi[j] = f.xi
    return est, xi


def diagnostics(x, rng, B, qs=QS):
    """TPW, its bootstrap SE, the median, the percentage and z gaps, and the bootstrap upper
    quantile of the shape at the middle threshold. rng draws the resamples exactly as
    estimators.bootstrap_reps (same streams as the main study)."""
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    n = x.size
    u = np.quantile(x, qs)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        est, xi = _fit_all(x, u)
        reps = np.full((B, len(u), len(MEASURES)), np.nan)
        xis = np.full((B, len(u)), np.nan)
        for b in range(B):
            reps[b], xis[b] = _fit_all(x[rng.integers(0, n, n)], u)
        out = {"xi_U90_mid": float(np.nanquantile(xis[:, J_MID], 0.9)) if np.isfinite(xis[:, J_MID]).any() else np.nan,
               "xi_mid": float(xi[J_MID])}
        for meas in TARGETS:
            k = MEASURES.index(meas)
            e, r = est[:, k], reps[:, :, k]
            w = tpw_weights(r, e)
            if not np.isfinite(w).any() or np.nansum(w) == 0:
                w = tpw_core(r, e)
            ok = np.isfinite(e) & np.isfinite(w) & (w > 0)
            if not ok.any():
                out.update({f"d_tpw_{meas}": np.nan, f"se_tpw_{meas}": np.nan, f"d_median_{meas}": np.nan,
                            f"gap_{meas}": np.nan, f"z_{meas}": np.nan})
                continue
            ww = w[ok] / w[ok].sum()
            tpw = float(np.sum(ww * e[ok]))
            comb = []
            for rb in r[:, ok]:
                f = np.isfinite(rb)
                if f.any():
                    comb.append(np.sum(ww[f] * rb[f]) / ww[f].sum())
            se = float(np.std(comb, ddof=1)) if len(comb) > 2 else np.nan
            med = float(np.median(e[np.isfinite(e)]))
            out.update({f"d_tpw_{meas}": tpw, f"se_tpw_{meas}": se, f"d_median_{meas}": med,
                        f"gap_{meas}": 100 * (math.exp(abs(math.log(tpw / med))) - 1) if tpw > 0 and med > 0 else np.nan,
                        f"z_{meas}": abs(tpw - med) / se if se and se > 0 else np.nan})
    return out


def _diag_stress(design, n, rep, B):
    return {"scenario": design, "n": n, "rep": rep, **diagnostics(simulate(design, n, rep), stream(BOOT_LABEL, design, n, rep), B)}


def run_diagnostics_stress():
    parts = []
    for n in STRESS_NS:
        for d in DESIGNS:
            path = cache_dir() / "checks" / f"diag_{d.replace(' ', '_')}_n{n}_R{STRESS_R}_B{STRESS_B}.csv"
            parts.append(cached_csv(path, lambda: pd.DataFrame(pmap(_diag_stress, [(d, n, r, STRESS_B) for r in range(STRESS_R)]))))
    return pd.concat(parts, ignore_index=True)


def evaluate_rules(d, meas="es0.99"):
    """Rules Z (z-gap > 2), E (xi_U90_mid >= 1), G25 (gap > 25%) and gap cut-offs: flagged share,
    relative RMSE of TPW in flagged / unflagged samples, recall and precision for TPW errors above 50%."""
    e = d[f"tpw_{meas}"].fillna(d[f"ew_{meas}"]) / d[f"true_{meas}"] - 1
    bad = np.abs(e) > 0.5
    rules = {"Z: z-gap > 2": d[f"z_{meas}"] > 2, "E: shape bound >= 1": d["xi_U90_mid"] >= 1}
    for c in (5, 10, 25, 50, 100):
        rules[f"gap > {c}%"] = d[f"gap_{meas}"] > c
    rows = []
    for nm, f in rules.items():
        f = f.fillna(False).astype(bool)
        rmse = lambda m: 100 * float(np.sqrt(np.nanmean(e[m] ** 2))) if m.any() else np.nan
        rows.append({"rule": nm, "flagged_%": 100 * f.mean(), "tpw_rmse_flagged": rmse(f), "tpw_rmse_unflagged": rmse(~f),
                     "recall_%": 100 * float((f & bad).sum() / max(bad.sum(), 1)),
                     "precision_%": 100 * float((f & bad).sum() / max(f.sum(), 1)) if f.any() else np.nan})
    return pd.DataFrame(rows)


def coverage(d, meas="es0.99"):
    t = d[f"true_{meas}"]
    lo, hi = d[f"d_tpw_{meas}"] - 1.645 * d[f"se_tpw_{meas}"], d[f"d_tpw_{meas}"] + 1.645 * d[f"se_tpw_{meas}"]
    ok = d[f"se_tpw_{meas}"].notna()
    rows = []
    for s, g in d[ok].groupby("scenario", sort=False):
        i = g.index
        rows.append({"design": s, "two_sided_90": 100 * float(((lo[i] <= t[i]) & (t[i] <= hi[i])).mean()),
                     "upper_95": 100 * float((t[i] <= hi[i]).mean()),
                     "margin_%": 100 * float(np.median(1.645 * d.loc[i, f"se_tpw_{meas}"] / d.loc[i, f"d_tpw_{meas}"]))})
    i = d[ok].index
    rows.append({"design": "All designs", "two_sided_90": 100 * float(((lo[i] <= t[i]) & (t[i] <= hi[i])).mean()),
                 "upper_95": 100 * float((t[i] <= hi[i]).mean()),
                 "margin_%": 100 * float(np.median(1.645 * d.loc[i, f"se_tpw_{meas}"] / d.loc[i, f"d_tpw_{meas}"]))})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# E. New simulation designs
# ----------------------------------------------------------------------------------------
BURR_TAU, BURR_LAM = 1.5, 2.0              # survival (1 + x^1.5)^-2: xi = 1/3, rho = -1/2
ARMAX_A = 0.5
G2_OMEGA, G2_ALPHA, G2_BETA, G2_NU = 0.01, 0.05, 0.94, 5.0


def sim_burr(n, rng):
    u = rng.random(n)
    return ((1 - u) ** (-1 / BURR_LAM) - 1) ** (1 / BURR_TAU)


def sim_armax(n, rng, burn=200):
    z = 1 / -np.log(rng.random(n + burn))          # unit Frechet
    x = np.empty(n + burn)
    x[0] = z[0]
    for t in range(1, n + burn):
        x[t] = max(ARMAX_A * x[t - 1], (1 - ARMAX_A) * z[t])
    return np.sqrt(x[burn:])


def sim_garch_persistent(n, rng, burn=1000):
    m = n + burn
    z = rng.standard_t(G2_NU, m) * np.sqrt((G2_NU - 2) / G2_NU)
    x = np.empty(m)
    s2 = G2_OMEGA / (1 - G2_ALPHA - G2_BETA)
    for t in range(m):
        x[t] = np.sqrt(s2) * z[t]
        s2 = G2_OMEGA + G2_ALPHA * x[t] ** 2 + G2_BETA * s2
    return x[burn:]


NEW_DESIGNS = {
    "GPD xi=0.7": lambda n, r: stats.genpareto.rvs(0.7, size=n, random_state=r),
    "Burr (rho=-0.5)": sim_burr,
    "ARMAX Frechet(2)": sim_armax,
    "GARCH persistent": sim_garch_persistent,
}


def _es_numeric(ppf, a):
    return float(integrate.quad(lambda p: ppf(p), a, 1, limit=500)[0] / (1 - a))


def new_truth():
    T = {}
    g = sim_garch_persistent(TRUTH_N, stream("R3_truth", "GARCH persistent"))
    burr_ppf = lambda p: ((1 - p) ** (-1 / BURR_LAM) - 1) ** (1 / BURR_TAU)
    frechet2_ppf = lambda p: (-np.log(p)) ** (-0.5)
    for a in sorted(set(VAR_LEVELS) | set(ES_LEVELS)):
        gv = float(np.quantile(g, a))
        T[a] = {"GPD xi=0.7": gpd_truth(0.7, a),
                "Burr (rho=-0.5)": (burr_ppf(a), _es_numeric(burr_ppf, a)),
                "ARMAX Frechet(2)": (frechet2_ppf(a), _es_numeric(frechet2_ppf, a)),
                "GARCH persistent": (gv, float(g[g > gv].mean()))}
    return T


def _new_rep(design, n, rep, B, truth):
    x = NEW_DESIGNS[design](n, stream("STRESS_R3", design, n, rep))
    out = {"scenario": design, "n": n, "rep": rep}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        out.update(estimate_all(x, stream("BOOT_R3", design, n, rep), B))
        out.update(extra_estimates(x, caps=CAPS_RUN, with_penk=True))
        out.update({f"diag_{k}": v for k, v in diagnostics(x, stream("BOOT_R3", design, n, rep), B).items()})
    out.update(truth_columns({a: truth[a][design] for a in truth}))
    return out


