def _grid_rep(design, n, rep, grid):
    from scipy.stats import trim_mean
    x = simulate(design, n, rep)
    qs = GRIDS[grid]
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        est, xi = _fit_all(x, np.quantile(x, qs))
        out = {"scenario": design, "n": n, "rep": rep, "grid": grid}
        for k, m in enumerate(MEASURES):
            e = est[:, k]
            fin = e[np.isfinite(e)]
            out[f"ew_{m}"] = float(fin.mean()) if fin.size else np.nan
            out[f"median_{m}"] = float(np.median(fin)) if fin.size else np.nan
            keep = np.isfinite(e) & (xi < 0.9)
            out[f"screen_{m}"] = float(e[keep].mean()) if keep.any() else np.nan
        out.update(extra_estimates(x, qs=qs))
    return out


