# New loss data: French commercial fire (CASdatasets), BMW and Siemens returns (evir)
# ----------------------------------------------------------------------------------------
FRECOMFIRE_URL = "https://raw.githubusercontent.com/dutangc/CASdatasets/master/data/frecomfire.rda"
EVIR_URL = "https://raw.githubusercontent.com/cran/evir/master/data/{}.rda"
FRECOMFIRE_N = 9613


def _download(url, path):
    import shutil
    import urllib.request
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=60) as r, open(path, "wb") as f:
            shutil.copyfileobj(r, f)
    return path


def load_frecomfire():
    """French commercial fire losses (FFSA, 1982-1996; CASdatasets 1.2-1): year, date, cost (FFR),
    cost2007 (thousand 2007 euros). Saved as data/french_fire_losses.csv with checksums."""
    import json
    import rdata
    out = DATA_DIR / "french_fire_losses.csv"
    if not out.exists():
        raw = _download(FRECOMFIRE_URL, RAW_DIR / "frecomfire_CASdatasets.rda")
        d = rdata.conversion.convert(rdata.parser.parse_file(str(raw)))["frecomfire"]
        d = pd.DataFrame({"year": np.asarray(d["Year"], dtype=int), "date": pd.to_datetime(d["OccurDate"]).dt.strftime("%Y-%m-%d"),
                          "cost": np.asarray(d["ClaimCost"], dtype=float), "cost2007": np.asarray(d["ClaimCost2007"], dtype=float)})
        assert len(d) == FRECOMFIRE_N and d.year.min() == 1982 and d.year.max() == 1996
        d.to_csv(out, index=False, float_format="%.10g")
        out.with_name("french_fire_losses_metadata.json").write_text(json.dumps(
            {"source": FRECOMFIRE_URL, "n": len(d), "sum_cost2007": round(float(d.cost2007.sum()), 3),
             "sha256_raw": sha256_file(raw), "sha256_csv": sha256_file(out)}, indent=2))
    return pd.read_csv(out, parse_dates=["date"])


def load_evir_returns(name):
    """Daily log returns of BMW or Siemens shares, 1973-1996 (R package evir). Returns losses in
    per cent (-100 x return) with dates."""
    import json
    import rdata
    out = DATA_DIR / f"{name}_losses_pct.csv"
    if not out.exists():
        raw = _download(EVIR_URL.format(name), RAW_DIR / f"{name}_evir.rda")
        obj = rdata.parser.parse_file(str(raw)).object.value[0]
        r, times, a = np.asarray(obj.value, dtype=float), None, obj.attributes
        while a is not None:
            tag = a.tag.referenced_object.value.value if a.tag.info.type.name == "REF" else a.tag.value.value
            car, cdr = a.value
            if tag == b"times":
                times = np.asarray(car.value, dtype=float)
            a = cdr if cdr.info.type.name == "LIST" else None
        d = pd.DataFrame({"date": pd.to_datetime(times, unit="s").strftime("%Y-%m-%d"), "loss": -100 * r})
        assert len(d) == 6146
        d.to_csv(out, index=False, float_format="%.10g")
        out.with_name(f"{name}_losses_metadata.json").write_text(json.dumps(
            {"source": EVIR_URL.format(name), "n": len(d), "sha256_raw": sha256_file(raw), "sha256_csv": sha256_file(out)}, indent=2))
    d = pd.read_csv(out, parse_dates=["date"])
    d["year"] = d["date"].dt.year
    return d


def loss_samples():
    """name -> list of (label, losses) with the full sample first, then each calendar year.
    French fire: 2007 prices, all years cut at the largest yearly minimum (common real reporting
    threshold), claims in date order. BMW, Siemens: full years 1973-1995 (1996 is incomplete)."""
    out = {}
    f = load_frecomfire().sort_values(["date"], kind="stable")
    thr = float(f.groupby("year")["cost2007"].min().max())
    f = f[f.cost2007 >= thr]
    out["French fire"] = [("1982-1996", f.cost2007.values)] + [(str(y), g.cost2007.values) for y, g in f.groupby("year")]
    for nm in ("bmw", "siemens"):
        d = load_evir_returns(nm)
        d = d[d.year <= 1995]
        out[nm.upper() if nm == "bmw" else "Siemens"] = [("1973-1995", d.loss.values)] + [(str(y), g.loss.values) for y, g in d.groupby("year")]
    return out, thr


def _data_rep(dataset, label, x, seed, B):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        out = {"dataset": dataset, "sample": label, "n": int(len(x))}
        out.update(estimate_all(np.asarray(x, dtype=float), np.random.default_rng(seed), B))
        out.update(extra_estimates(x, caps=CAPS_RUN, with_penk=True))
        out.update({f"diag_{k}": v for k, v in diagnostics(x, np.random.default_rng(seed), B).items()})
    return out


SEED_BASE = {"French fire": 5000, "BMW": 6000, "Siemens": 7000}


def run_new_data():
    def compute():
        samples, _ = loss_samples()
        jobs = []
        for nm, lst in samples.items():
            for i, (lab, x) in enumerate(lst):
                jobs.append((nm, lab, x, SEED_BASE[nm] + i, DANISH_B))
        return pd.DataFrame(pmap(_data_rep, jobs))
    return cached_csv(cache_dir() / "checks" / f"new_data_B{DANISH_B}.csv", compute)


def run_penk_old_data():
    """pen-k for the Danish losses and the Norwegian claims at 2012 prices (no bootstrap needed)."""
    def compute():
        d = load_danish()
        jobs = [("danish", "1980-1990", d["loss"].values)] + [("danish", str(y), g["loss"].values) for y, g in d.groupby("year")]
        jobs += [("norway_real", nm, x) for nm, x in norfire_real_samples()[1]]
        rows = []
        for kind, nm, x in jobs:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                est, _ = per_threshold_fitter(np.asarray(x, dtype=float), np.quantile(x, QS), fit_gpd_penalised_k)
            rows.append({"kind": kind, "sample": nm, **{f"penk_{m}": float(np.nanmean(est[:, k])) for k, m in enumerate(MEASURES)}})
        return pd.DataFrame(rows)
    return cached_csv(cache_dir() / "checks" / "penk_old_data.csv", compute)


def _diag_old(kind, name, x, seed, B):
    return {"kind": kind, "sample": name, **diagnostics(x, np.random.default_rng(seed), B)}


def run_diag_old_data():
    """Diagnostics (z-gap, shape bound, SE) for the Danish and Norwegian samples, same seeds as the main analysis."""
    def compute():
        d = load_danish()
        jobs = [("danish", "1980-1990", d["loss"].values, 1985)] + [("danish", str(y), g["loss"].values, 2000 + i) for i, (y, g) in enumerate(d.groupby("year"))]
        jobs += [("norway_real", nm, x, 3100 if i == 0 else 3200 + i - 1) for i, (nm, x) in enumerate(norfire_real_samples()[1])]
        return pd.DataFrame(pmap(_diag_old, [(k, nm, x, s, DANISH_B) for k, nm, x, s in jobs]))
    return cached_csv(cache_dir() / "checks" / "diag_old_data.csv", compute)


# ----------------------------------------------------------------------------------------
# F. Out-of-sample scoring with the FZ0 loss
# ----------------------------------------------------------------------------------------
def fz0(y, v, e, a):
    """Average FZ0 loss of (VaR v, ES e) at level a over losses y (losses positive; e > 0)."""
    y = np.asarray(y, dtype=float)
    if not (np.isfinite(v) and np.isfinite(e) and e > 0):
        return np.nan
    return float(np.mean((y > v) * (y - v) / ((1 - a) * e) + v / e + np.log(e) - 1))


def oos_scores(frame, samples, methods, levels=(0.975, 0.99)):
    """frame: one row per sample label (full sample first, then years in order) with <m>_var<a>,
    <m>_es<a>; samples: list of (label, losses). Scores the year-t estimate on year t+1 losses."""
    labs = [lab for lab, _ in samples][1:]
    xs = dict(samples)
    rows = []
    t = frame.set_index("sample")
    for a in levels:
        for m in methods:
            sc = []
            for y0, y1 in zip(labs[:-1], labs[1:]):
                v = t.loc[y0, f"{m}_var{a}"] if f"{m}_var{a}" in t else np.nan
                e = t.loc[y0, f"{m}_es{a}"] if f"{m}_es{a}" in t else np.nan
                if not np.isfinite(e) or not np.isfinite(v):
                    v, e = t.loc[y0, f"ew_var{a}"], t.loc[y0, f"ew_es{a}"]
                sc.append(fz0(xs[y1], v, e, a))
            rows.append({"level": a, "method": m, "mean_fz0": float(np.nanmean(sc)), "n_pairs": int(np.isfinite(sc).sum()),
                         "scores": sc})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# Dynamic EVT: McNeil-Frey GARCH-EVT forecasts with every protection (BMW, Siemens)
# ----------------------------------------------------------------------------------------
def _bt_series(name, losses, seed):
    return rolling_forecasts(losses, BT_WINDOW, BT_REFIT, BT_B, seed, label=name, max_days=BT_MAX_DAYS, extra=True)


def run_dynamic():
    """Rolling one-day forecasts (window BT_WINDOW, refit every BT_REFIT days) for BMW and Siemens
    daily losses with all protections (seeds 8000, 8001). Returns forecasts and backtest rows."""
    fcs = {}
    todo = []
    for i, nm in enumerate(("bmw", "siemens")):
        d = load_evir_returns(nm).set_index("date")["loss"]
        path = cache_dir() / "checks" / f"dynamic_{nm}_w{BT_WINDOW}_r{BT_REFIT}_B{BT_B}.csv"
        if path.exists():
            fcs[nm] = pd.read_csv(path, index_col=0, parse_dates=True)
        else:
            todo.append((nm, d, 8000 + i, path))
    for (nm, _, _, path), fc in zip(todo, pmap(_bt_series, [t[:3] for t in todo])):
        path.parent.mkdir(parents=True, exist_ok=True)
        fc.to_csv(path)
        fcs[nm] = fc
    bt = pd.DataFrame([r for k, fc in fcs.items() for r in backtest_rows(fc, k, BT_METHODS_ALL)])
    return fcs, bt


def export_eqd_data():
    """Samples of all five loss data sets (full sample and years) for R/eqd.R."""
    folder = cache_dir() / "checks" / "eqd_data"
    folder.mkdir(parents=True, exist_ok=True)
    d = load_danish()
    sets = {"Danish": [("1980-1990", d["loss"].values)] + [(str(y), g["loss"].values) for y, g in d.groupby("year")],
            "Norway": norfire_real_samples()[1]}
    sets.update(loss_samples()[0])
    rows = []
    for nm, lst in sets.items():
        for lab, x in lst:
            f = f"{nm.replace(' ', '_')}_{lab}.csv"
            pd.DataFrame({"x": np.asarray(x, dtype=float)}).to_csv(folder / f, index=False, float_format="%.15g")
            rows.append({"scenario": nm, "n": len(x), "rep": lab, "file": f})
    pd.DataFrame(rows).to_csv(folder / "index.csv", index=False)
    return folder


# ----------------------------------------------------------------------------------------
# G. Sensitivity of the fixed constants: screening level and shape bound
# ----------------------------------------------------------------------------------------
SCREEN_LEVELS = (0.85, 0.9, 0.95)
BOUND_QUANTILES = (0.8, 0.9, 0.95)


def sensitivity_sample(x, rng, B):
    """Screened EW at three shape levels, and the bootstrap quantiles of the fitted shape at
    the middle threshold. The resamples are drawn exactly as in diagnostics() (same stream)."""
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    n = x.size
    u = np.quantile(x, QS)
    out = {}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        est, xi = _fit_all(x, u)
        for lev in SCREEN_LEVELS:
            for k, meas in enumerate(MEASURES):
                keep = np.isfinite(est[:, k]) & (xi < lev)
                out[f"screen{int(round(lev * 100))}_{meas}"] = float(est[keep, k].mean()) if keep.any() else np.nan
        um = u[J_MID]
        xs = np.full(B, np.nan)
        for b in range(B):
            xb = x[rng.integers(0, n, n)]
            f = fit_gpd(xb[xb > um] - um)
            if f.ok:
                xs[b] = f.xi
    for q in BOUND_QUANTILES:
        out[f"xi_U{int(round(q * 100))}_mid"] = float(np.nanquantile(xs, q)) if np.isfinite(xs).any() else np.nan
    return out


def _sens_main(design, n, rep, B):
    return {"scenario": design, "n": n, "rep": rep, **sensitivity_sample(simulate(design, n, rep), stream(BOOT_LABEL, design, n, rep), B)}


def _sens_new(design, n, rep, B):
    x = NEW_DESIGNS[design](n, stream("STRESS_R3", design, n, rep))
    return {"scenario": design, "n": n, "rep": rep, **sensitivity_sample(x, stream("BOOT_R3", design, n, rep), B)}


def run_sensitivity():
    """Screening levels 0.85/0.9/0.95 and shape-bound quantiles 0.8/0.9/0.95 for the 2,400 main and
    1,200 additional-design samples."""
    parts = []
    for n in STRESS_NS:
        for d in DESIGNS:
            path = cache_dir() / "checks" / f"sens_{d.replace(' ', '_')}_n{n}_R{STRESS_R}_B{STRESS_B}.csv"
            parts.append(cached_csv(path, lambda: pd.DataFrame(pmap(_sens_main, [(d, n, r, STRESS_B) for r in range(STRESS_R)]))))
        for d in NEW_DESIGNS:
            path = cache_dir() / "checks" / f"sensnew_{d.replace(' ', '_').replace('(', '').replace(')', '').replace('=', '')}_n{n}_R{STRESS_R}_B{STRESS_B}.csv"
            parts.append(cached_csv(path, lambda: pd.DataFrame(pmap(_sens_new, [(d, n, r, STRESS_B) for r in range(STRESS_R)]))))
    return pd.concat(parts, ignore_index=True)


# ----------------------------------------------------------------------------------------
# H. Extremal index (intervals estimator of Ferro and Segers, 2003)
# ----------------------------------------------------------------------------------------
def extremal_index(x, q):
    """Intervals estimator of the extremal index for exceedances of the empirical q-quantile,
    observations taken in the given order (Ferro and Segers, 2003, eq. 4)."""
    x = np.asarray(x, dtype=float)
    s = np.flatnonzero(x > np.quantile(x, q))
    if s.size < 3:
        return np.nan
    t = np.diff(s).astype(float)
    nm1 = t.size
    if t.max() <= 2:
        th = 2 * t.sum() ** 2 / (nm1 * (t ** 2).sum())
    else:
        den = nm1 * ((t - 1) * (t - 2)).sum()
        th = 2 * (t - 1).sum() ** 2 / den if den > 0 else np.nan
    return float(min(1.0, th))


def run_extremal_index(qs=(0.90, 0.95)):
    """Extremal index of the loss data (in time order) and, on average, of the simulated designs."""
    rows = []
    d = load_danish().sort_values("date", kind="stable")
    data = {"Danish": d["loss"].values}
    s, _ = loss_samples()
    data.update({k: v[0][1] for k, v in s.items()})
    for nm, x in data.items():
        rows.append({"set": "data", "name": nm, "n": len(x), **{f"theta_q{int(q * 100)}": extremal_index(x, q) for q in qs}})
    for des in ("Student-t3", "Regime blocked", "GARCH(1,1)-t5"):
        for n in STRESS_NS:
            th = [[extremal_index(simulate(des, n, r), q) for q in qs] for r in range(STRESS_R)]
            rows.append({"set": "main design", "name": des, "n": n, **{f"theta_q{int(q * 100)}": float(np.nanmean([t[i] for t in th])) for i, q in enumerate(qs)}})
    for des in ("ARMAX Frechet(2)", "GARCH persistent"):
        for n in STRESS_NS:
            th = [[extremal_index(NEW_DESIGNS[des](n, stream("STRESS_R3", des, n, r)), q) for q in qs] for r in range(STRESS_R)]
            rows.append({"set": "additional design", "name": des, "n": n, **{f"theta_q{int(q * 100)}": float(np.nanmean([t[i] for t in th])) for i, q in enumerate(qs)}})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------------------
# I. Designs near the boundary and non-Pareto tails; bootstrap size
# ----------------------------------------------------------------------------------------
TP_ALPHA, TP_LAMBDA = 1.25, 0.01          # tempered Pareto: survival (1 + x)^-1.25 exp(-0.01 x)
MIX_P, MIX_XI, MIX_SIGMA = 0.1, 0.6, 3.0  # 0.9 LN(0, 1) + 0.1 GPD(0.6, 3)


def sim_tempered(n, rng):
    lomax = (1 - rng.random(n)) ** (-1 / TP_ALPHA) - 1
    return np.minimum(lomax, rng.exponential(1 / TP_LAMBDA, n))


def sim_mixture(n, rng):
    z = rng.random(n) < MIX_P
    return np.where(z, stats.genpareto.rvs(MIX_XI, scale=MIX_SIGMA, size=n, random_state=rng),
                    rng.lognormal(0.0, 1.0, n))


NEW4_DESIGNS = {
    "GPD xi=0.6": lambda n, r: stats.genpareto.rvs(0.6, size=n, random_state=r),
    "GPD xi=0.8": lambda n, r: stats.genpareto.rvs(0.8, size=n, random_state=r),
    "GPD xi=0.9": lambda n, r: stats.genpareto.rvs(0.9, size=n, random_state=r),
    "Lognormal": lambda n, r: r.lognormal(0.0, 1.0, n),
    "Weibull (k=0.5)": lambda n, r: r.weibull(0.5, n),
    "Tempered Pareto": sim_tempered,
    "LN-GPD mixture": sim_mixture,
}


def _ppf_from_sf(sf, p, hi=1e12):
    from scipy.optimize import brentq
    return brentq(lambda x: sf(x) - (1 - p), 0.0, hi, xtol=1e-12, rtol=1e-12, maxiter=500)


def new4_truth():
    tp_sf = lambda x: (1 + x) ** (-TP_ALPHA) * np.exp(-TP_LAMBDA * x)
    mix_sf = lambda x: (1 - MIX_P) * stats.lognorm.sf(x, 1.0) + MIX_P * stats.genpareto.sf(x, MIX_XI, scale=MIX_SIGMA)
    ppfs = {"Lognormal": lambda p: stats.lognorm.ppf(p, 1.0),
            "Weibull (k=0.5)": lambda p: stats.weibull_min.ppf(p, 0.5),
            "Tempered Pareto": lambda p: _ppf_from_sf(tp_sf, p),
            "LN-GPD mixture": lambda p: _ppf_from_sf(mix_sf, p)}
    T = {}
    for a in sorted(set(VAR_LEVELS) | set(ES_LEVELS)):
        T[a] = {f"GPD xi={x}": gpd_truth(x, a) for x in (0.6, 0.8, 0.9)}
        for d, f in ppfs.items():
            T[a][d] = (float(f(a)), _es_numeric(f, a))
    return T


def _new4_rep(design, n, rep, B, truth):
    x = NEW4_DESIGNS[design](n, stream("STRESS_R4", design, n, rep))
    out = {"scenario": design, "n": n, "rep": rep}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        out.update(estimate_all(x, stream("BOOT_R4", design, n, rep), B))
        out.update(extra_estimates(x, caps=CAPS_RUN, with_penk=True))
        out.update({f"diag_{k}": v for k, v in diagnostics(x, stream("BOOT_R4", design, n, rep), B).items()})
    out.update(truth_columns({a: truth[a][design] for a in truth}))
    return out


def run_new4_designs():
    truth = new4_truth()
    parts = []
    for n in STRESS_NS:
        for d in NEW4_DESIGNS:
            slug = d.replace(' ', '_').replace('(', '').replace(')', '').replace('=', '')
            path = cache_dir() / "checks" / f"new4_{slug}_n{n}_R{STRESS_R}_B{STRESS_B}.csv"
            parts.append(cached_csv(path, lambda: pd.DataFrame(pmap(_new4_rep, [(d, n, r, STRESS_B, truth) for r in range(STRESS_R)]))))
    return pd.concat(parts, ignore_index=True)


def _bound_B(design, n, rep, Bmax=500):
    """Shape bound from the first 50, 100, 200 and Bmax resamples of the main-study stream."""
    x = simulate(design, n, rep)
    rng = stream(BOOT_LABEL, design, n, rep)
    um = np.quantile(x, QS)[J_MID]
    xs = np.full(Bmax, np.nan)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for b in range(Bmax):
            xb = x[rng.integers(0, n, n)]
            f = fit_gpd(xb[xb > um] - um)
            if f.ok:
                xs[b] = f.xi
    out = {"scenario": design, "n": n, "rep": rep}
    for B in (50, 100, 200, Bmax):
        out[f"U90_B{B}"] = float(np.nanquantile(xs[:B], 0.9)) if np.isfinite(xs[:B]).any() else np.nan
    return out


def run_bound_B():
    parts = []
    for n in STRESS_NS:
        for d in DESIGNS:
            path = cache_dir() / "checks" / f"boundB_{d.replace(' ', '_')}_n{n}_R{STRESS_R}.csv"
            parts.append(cached_csv(path, lambda: pd.DataFrame(pmap(_bound_B, [(d, n, r) for r in range(STRESS_R)]))))
    return pd.concat(parts, ignore_index=True)


# ----------------------------------------------------------------------------------------
# J. Profile likelihood of ES at one threshold
# ----------------------------------------------------------------------------------------
def _gpd_loglik(xi, beta, y):
    if beta <= 0:
        return -np.inf
    z = 1 + xi * y / beta
    if np.any(z <= 0):
        return -np.inf
    if abs(xi) < 1e-10:
        return float(-y.size * np.log(beta) - y.sum() / beta)
    return float(-y.size * np.log(beta) - (1 + 1 / xi) * np.log(z).sum())


def _beta_for_es(xi, e, u, r):
    """Scale at which the POT ES equals e: ES = u + beta * {(r^-xi - 1)/xi + 1}/(1 - xi)."""
    g = (r ** (-xi) - 1) / xi + 1 if abs(xi) > 1e-10 else -np.log(r) + 1
    return (e - u) * (1 - xi) / g


def profile_es(y, u, p, alpha, es_grid, xi_grid=None):
    """Profile log-likelihood of the ES at level alpha for GPD excesses y over threshold u with
    exceedance probability p (taken as known), over a grid of ES values; also the maximized
    log-likelihood and its supremum at xi = 1 (the limit of the profile as ES grows)."""
    from scipy.optimize import minimize_scalar
    y = np.asarray(y, dtype=float)
    r = (1 - alpha) / p
    xi_grid = np.concatenate([np.linspace(-0.45, 0.95, 800), 1 - np.geomspace(0.05, 1e-9, 900)]) if xi_grid is None else xi_grid
    prof = []
    for e in es_grid:
        prof.append(max(_gpd_loglik(x, _beta_for_es(x, e, u, r), y) for x in xi_grid))
    f = fit_gpd(y)
    lmax = _gpd_loglik(f.xi, f.beta, y) if f.ok else np.nan
    res = minimize_scalar(lambda lb: -_gpd_loglik(1.0, np.exp(lb), y), bounds=(np.log(y.mean()) - 10, np.log(y.mean()) + 10), method="bounded")
    return np.array(prof), lmax, -res.fun, f


def lr_xi1(x, q=0.91):
    """Likelihood-ratio statistic for xi = 1 at the empirical q-quantile (signed: 0 if xi_hat >= 1)."""
    x = np.asarray(x, dtype=float)
    u = np.quantile(x, q)
    y = x[x > u] - u
    _, lmax, l1, f = profile_es(y, u, y.size / x.size, 0.99, [], xi_grid=[0.0])
    if not f.ok:
        return np.nan, np.nan
    return (0.0 if f.xi >= 1 else 2 * (lmax - l1)), f.xi


def _lr_main(design, n, rep):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        lr, xi = lr_xi1(simulate(design, n, rep))
    return {"scenario": design, "n": n, "rep": rep, "lr_xi1": lr, "xi_mid_ml": xi}


def _lr_new(design, n, rep):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        lr, xi = lr_xi1(NEW_DESIGNS[design](n, stream("STRESS_R3", design, n, rep)))
    return {"scenario": design, "n": n, "rep": rep, "lr_xi1": lr, "xi_mid_ml": xi}


def run_lr():
    """LR statistic for xi = 1 at the middle threshold for the main and additional-design samples:
    the 90% likelihood-ratio confidence set of the ES is unbounded when it is below 2.706."""
    jobs_m = [(d, n, r) for n in STRESS_NS for d in DESIGNS for r in range(STRESS_R)]
    jobs_n = [(d, n, r) for n in STRESS_NS for d in NEW_DESIGNS for r in range(STRESS_R)]
    path = cache_dir() / "checks" / f"lr_xi1_R{STRESS_R}.csv"
    return cached_csv(path, lambda: pd.DataFrame(pmap(_lr_main, jobs_m) + pmap(_lr_new, jobs_n)))


def _corr_rep(design, n, rep, B=100):
    """Spearman correlation across bootstrap resamples between threshold estimates (main-study streams)."""
    x = simulate(design, n, rep)
    u = np.quantile(x, QS)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        reps = bootstrap_reps(x, u, B, stream(BOOT_LABEL, design, n, rep))
    out = {"scenario": design, "n": n, "rep": rep}
    for meas in ("var0.99", "es0.99"):
        r = pd.DataFrame(reps[:, :, MEASURES.index(meas)]).corr(method="spearman", min_periods=20).values
        out[f"adj_{meas}"] = float(np.nanmedian(np.diag(r, 1)))
        out[f"ends_{meas}"] = float(r[0, -1])
        out[f"all_{meas}"] = float(np.nanmedian(r[np.triu_indices_from(r, 1)]))
    return out


def run_threshold_correlation(n=500, R=25):
    path = cache_dir() / "checks" / f"corr_n{n}_R{R}.csv"
    return cached_csv(path, lambda: pd.DataFrame(pmap(_corr_rep, [(d, n, r) for d in DESIGNS for r in range(R)])))

# ==========================================================================================
# TABLES FOR THE RELIABILITY CHECKS
# ==========================================================================================
"""Tables of the reliability checks, the additional designs and data, the out-of-sample and
dynamic comparisons and the identification analysis.

The switch heuristics ("swcap", "swtpw") use penalized likelihood when the shape check fires and
the capped shape or TPW otherwise; they are exploratory. The EQD and Bayesian results on the
data come from R/eqd.R and the R benchmark script when R is available.
"""
import glob

import numpy as np
import pandas as pd


FAM = [("ew", "Equal weights"), ("median", "Median"), ("screen", "Screened EW"), ("cap", "Capped shape"),
       ("pen", "Penalised"), ("chw", "Bias-reduced Hill"), ("tpw", "TPW")]
SW = [("swcap", "Switch (capped)"), ("swtpw", "Switch (TPW)")]


def add_switch(g, flag_col="xi_U90_mid"):
    """Check-and-switch: penalised likelihood when the shape bound is >= 1, otherwise the base method."""
    f = (g[flag_col] >= 1).values
    for meas in MEASURES:
        for base, nm in (("cap", "swcap"), ("tpw", "swtpw"), ("median", "swmed")):
            g[f"{nm}_{meas}"] = np.where(f, g[f"pen_{meas}"], g[f"{base}_{meas}"].fillna(g[f"ew_{meas}"]))
    return g


def stress_frame():
    stress = run_stress()
    stress = fill_fallbacks(stress[stress["ok"].astype(bool)].copy(),
                            ["single", "ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv"])
    d = prepare_stress(stress, run_robust_combiners(), run_extra_stress())
    d = d.merge(run_diagnostics_stress(), on=["scenario", "n", "rep"]).merge(run_penk_stress(), on=["scenario", "n", "rep"])
    return add_switch(d)


def new_design_frame():
    nd = run_new_designs()
    nd = fill_fallbacks(nd, [m for m in METHODS if f"{m}_es0.99" in nd])
    for c in [c for c in nd if c.startswith("diag_")]:
        nd[c[5:]] = nd[c]
    return add_switch(nd)


def grids_table(d):
    """Relative RMSE (%) of the protections on the main, lower and higher grids (n = 250, 1,000).
    TPW on the alternative grids comes from the robustness study (same samples and streams)."""
    rob = run_robustness()
    rob = fill_fallbacks(rob[rob["ok"].astype(bool)].copy(), ["ew", "tpw_core", "tpw"])
    gp = run_grids_protections()
    tr = d[["scenario", "n", "rep"] + [c for c in d if c.startswith("true_")]]
    rows = []
    for name in ("base", "low", "high"):
        x = d[d.n.isin([250, 1000])] if name == "base" else gp[gp.grid == name].merge(tr, on=["scenario", "n", "rep"])
        rb = rob[rob.variant == f"grid_{name}"]
        for meas in ("es0.975", "es0.99", "var0.999"):
            r = {"grid": name, "measure": meas}
            for m in ("ew", "median", "screen", "cap", "pen", "chw"):
                r[m] = _cell_rmse(x, m, meas)
            r["tpw"] = _cell_rmse(rb, "tpw", meas)
            r["ew_check"] = _cell_rmse(rb, "ew", meas)
            r["pen_low20"] = 100 * float((_err(x, "pen", meas) < -0.2).mean())
            r["tpw_low20"] = 100 * float((_err(rb, "tpw", meas) < -0.2).mean())
            rows.append(r)
    return pd.DataFrame(rows)


def simulation_tables():
    d, nd = stress_frame(), new_design_frame()
    out = {"checks_es99": evaluate_rules(d, "es0.99"), "checks_es975": evaluate_rules(d, "es0.975"),
           "checks_by_n": pd.concat([evaluate_rules(d[d.n == n], "es0.99").assign(n=n) for n in (250, 500, 1000)]),
           "bootstrap_interval_coverage": coverage(d, "es0.99").merge(coverage(d, "es0.975"), on="design", suffixes=("_es99", "_es975")),
           "checks_additional_designs": evaluate_rules(nd, "es0.99"), "bootstrap_interval_coverage_additional": coverage(nd, "es0.99")}
    M = [("ew", "EW"), ("median", "Median"), ("screen", "Screened"), ("cap", "Capped"), ("pen", "Penalized"),
         ("penk", "Pen-k"), ("chw", "BR-Hill"), ("tpw", "TPW")]
    out["penalty_k_comparison"] = table_protection(d, measures=("es0.975", "es0.99", "var0.999"), methods=M)
    out["by_design_es99_all"] = pd.concat([table_by_design(d, "es0.99", methods=FAM + SW),
                                                 table_by_design(nd, "es0.99", methods=FAM + SW)], ignore_index=True)
    allm = FAM[:1] + [("cv", "CV-BMA"), ("vpw", "VPW")] + FAM[1:] + SW
    out["protections_accuracy_with_switch"] = table_protection(d, methods=allm)
    out["protections_accuracy_additional"] = table_protection(nd, methods=allm)
    out["capital_costs_with_switch"] = table_capital(d, methods=FAM + SW)
    rm = out["capital_relative_costs_with_switch"] = table_regret(d, methods=FAM + SW)
    out["capital_costs_additional"] = table_capital(nd, methods=FAM + SW)
    rn = out["capital_relative_costs_additional"] = table_regret(nd, methods=FAM + SW)
    summ = pd.concat([rm.assign(set="main"), rn.assign(set="new")])
    out["capital_worst_relative_cost"] = summ.pivot_table(index="method", columns=["set", "measure"], values="max_regret")
    out["protections_threshold_grids"] = grids_table(d)
    for k, v in out.items():
        if v is not None:
            save_table(v, k, index=(k == "capital_worst_relative_cost"))
    return out


def r_results(sub, stored):
    """Results of an R run in outputs/cache/<mode>/checks/<sub>/, or stored results in
    data/published_rules/<stored> if present."""
    files = sorted(glob.glob(str(cache_dir() / "checks" / sub / "part*.csv")))
    if files:
        return pd.concat([pd.read_csv(f) for f in files], ignore_index=True)
    p = DATA_DIR / "published_rules" / stored
    return pd.read_csv(p) if p.exists() else None


def _fill_tpw(t):
    for meas in MEASURES:
        t[f"tpw_{meas}"] = t[f"tpw_{meas}"].fillna(t[f"tpw_core_{meas}"])
    return t


def data_frames():
    """One frame per data set (full sample first, then years) with every method, the shape
    bound, the switch rules, the empirical ES and, where available, EQD and Bayesian estimates."""
    cd = cache_dir() / "checks"
    ex, dd = run_extra_real(), load_danish()
    pk = run_penk_old_data().copy(); pk["sample"] = pk["sample"].astype(str)
    do = run_diag_old_data().copy(); do["sample"] = do["sample"].astype(str)
    def old(frame, kind):
        return (real_frame(frame, ex, kind).merge(pk[pk.kind == kind].drop(columns="kind"), on="sample")
                .merge(do[do.kind == kind].drop(columns="kind"), on="sample"))
    new = run_new_data().copy(); new["sample"] = new["sample"].astype(str)
    for c in [c for c in new if c.startswith("diag_")]:
        new[c[5:]] = new[c]
    samples, _ = loss_samples()
    F = {"Danish": (old(run_danish(), "danish"), [("1980-1990", dd["loss"].values)] + [(str(y), g["loss"].values) for y, g in dd.groupby("year")]),
         "Norwegian": (old(run_norfire_real(), "norway_real"), norfire_real_samples()[1])}
    for nm in ["French fire", "BMW", "Siemens"]:
        F[nm] = (_fill_tpw(new[new.dataset == nm].reset_index(drop=True)), samples[nm])
    EQ, BA = r_results("eqd_data_out", "eqd_data_results.csv"), r_results("bayes_new_out", "bayes_new_data_results.csv")
    rcd, rcn = load_rcomp("danish"), load_rcomp("norfire_real")
    names = {"Danish": "Danish", "Norwegian": "Norway", "French fire": "French fire", "BMW": "BMW", "Siemens": "Siemens"}
    out = {}
    for nm, (t, smp) in F.items():
        t = t.copy()
        if EQ is not None:
            e = EQ[EQ.scenario == names[nm]].copy(); e["sample"] = e["rep"].astype(str)
            t = t.merge(e[["sample"] + [c for c in e if c.startswith("eqd_")]], on="sample", how="left")
        b = None
        if nm == "Danish" and rcd is not None:
            b = rcd.copy(); b["sample"] = np.where(b.rep == 0, "1980-1990", b.rep.astype(str))
        elif nm == "Norwegian" and rcn is not None:
            b = rcn.copy(); b["sample"] = np.where(b.rep == 0, "1976-1992", b.rep.astype(str))
        elif nm not in ("Danish", "Norwegian") and BA is not None:
            b = BA[BA.scenario == nm].copy(); b["sample"] = b["rep"].astype(str)
        if b is not None:
            t = t.merge(b[["sample"] + [c for c in b if c.startswith("nbma_")]], on="sample", how="left")
        t = add_switch(t)
        t = add_empirical(t, dict(smp))
        t["flagE"] = (t["xi_U90_mid"] >= 1).values
        out[nm] = (t, smp)
    return out


def data_tables():
    M = ["ew", "cv", "vpw", "median", "screen", "cap", "pen", "penk", "chw", "tpw", "swcap", "swtpw", "eqd", "nbma"]
    stab, rows = [], []
    for nm, (t, smp) in data_frames().items():
        full, yr = t.iloc[0], t.iloc[1:]
        ms = [m for m in M if f"{m}_es0.99" in t and not t[f"{m}_es0.99"].isna().all()]
        for m in ms:
            v = yr[f"{m}_es0.99"].fillna(yr["ew_es0.99"]).values
            f0 = full[f"{m}_es0.99"]
            ld = np.log(v / f0) if np.isfinite(f0) else np.full(len(v), np.nan)
            stab.append({"data": nm, "method": m, "maxratio": float(np.exp(np.nanmax(ld))) if np.isfinite(ld).any() else np.nan,
                         "below_emp": int(np.nansum(v < yr["emp_es0.99"].values)), "years": len(yr), "flagged": int(yr.flagE.sum())})
        sc = oos_scores(t, smp, ms)
        for a, g in sc.groupby("level"):
            base = np.array(g.set_index("method").loc["ew", "scores"])
            for _, r in g.iterrows():
                dl = np.array(r.scores) - base
                rows.append({"data": nm, "level": a, "method": r.method, "mean_fz0": r.mean_fz0, "diff_vs_ew": float(np.nanmean(dl)),
                             "years_better": int(np.nansum(dl < -1e-12)), "pairs": int(np.isfinite(dl).sum())})
    S, O = pd.DataFrame(stab), pd.DataFrame(rows)
    save_table(S, "data_stability"); save_table(O, "data_out_of_sample")
    return S, O


def dynamic_tables():
    """Rolling GARCH-EVT forecasts with all protections (BMW, Siemens) and their backtests."""
    fcs, bt = run_dynamic()
    save_table(bt, "dynamic_backtests")
    return bt


def run_reliability_analysis():
    log("checks: simulation tables"); out = simulation_tables()
    log("checks: sensitivity of the constants and extremal index")
    save_table(sensitivity_table(stress_frame(), new_design_frame(), run_sensitivity()), "constants_sensitivity")
    save_table(run_extremal_index(), "extremal_index")
    log("checks: identification, calibration, out-of-sample inference, designs near the boundary"); identification_and_calibration_tables()
    log("checks: data tables"); data_tables()
    log("checks: dynamic backtests"); dynamic_tables()


def eqd_stress_table(eqd, d=None, rules=None):
    """EQD threshold selection (Murphy et al., 2025; mev) on the 600 stress samples processed by R,
    with equal weights, the Bayesian scheme, ForwardStop, TPW, penalised likelihood, the capped
    shape and the switch rule on the same samples. Missing estimates fall back to equal weights."""
    d = stress_frame() if d is None else d
    rules = load_rcomp("stress") if rules is None else rules
    key = ["scenario", "n", "rep"]
    x = eqd.merge(d, on=key, how="left")
    if rules is not None:
        x = x.merge(rules[key + [c for c in rules if c.startswith(("nbma_", "fstop_"))]], on=key, how="left")
    M = [("ew", "Equal weights"), ("nbma", "Bayesian, averaged"), ("fstop", "ForwardStop"), ("eqd", "EQD"),
         ("median", "Median"), ("cap", "Capped shape"), ("pen", "Penalized"), ("tpw", "TPW"), ("swcap", "Switch (capped)")]
    rows = []
    for meas in ("var0.99", "es0.975", "es0.99"):
        for m, lab in M:
            if f"{m}_{meas}" not in x:
                continue
            v = x[f"{m}_{meas}"]
            miss = float(v.isna().mean() * 100)
            e = v.fillna(x[f"ew_{meas}"]) / x[f"true_{meas}"] - 1
            rows.append({"measure": meas, "method": lab, "rmse": 100 * float(np.sqrt(np.nanmean(e ** 2))),
                         "median_error": 100 * float(np.nanmedian(e)), "over100": 100 * float((e > 1).mean()),
                         "under20": 100 * float((e < -0.2).mean()), "missing_%": miss})
    return pd.DataFrame(rows)


def sensitivity_table(d, nd, sens):
    """Sensitivity of the fixed constants: screening level, cap and the shape-bound check (its
    bootstrap quantile and the level at which it fires), for the 99% ES. Relative cost is
    measured against the best of the main methods at the same cost ratio (lambda = 1-20)."""
    key = ["scenario", "n", "rep"]
    lambdas = (1, 2, 3, 5, 10, 20)
    rows = []
    for setname, g in (("main", d), ("additional", nd)):
        g = g.merge(sens, on=key, how="left", suffixes=("", "_s"))
        best = {}
        terms0 = [capital_terms(g, m, "es0.99") for m, _ in FAM + SW]
        for l in lambdas:
            best[l] = min(l * s + e for s, e in terms0)
        variants = []
        for lev in (85, 90, 95):
            variants.append(("Screened EW", f"shape < {lev / 100:.2f}", f"screen{lev}"))
        for c, col in ((0.7, "cap70"), (0.8, "cap"), (0.9, "cap90")):
            variants.append(("Capped shape", f"ξ ≤ {c}", col))
        for q in (80, 90, 95):
            for lev in (0.9, 1.0, 1.1):
                f = (g[f"xi_U{q}_mid"] >= lev).values
                col = f"sw_q{q}_l{int(lev * 100)}"
                g[f"{col}_es0.99"] = np.where(f, g["pen_es0.99"], g["cap_es0.99"].fillna(g["ew_es0.99"]))
                g[f"{col}_flag"] = f
                variants.append(("Switch (capped)", f"{q}th percentile ≥ {lev}", col))
        for c, cc in ((0.7, "cap70"), (0.9, "cap90")):
            f = (g["xi_U90_mid"] >= 1).values
            col = f"sw_c{cc}"
            g[f"{col}_es0.99"] = np.where(f, g["pen_es0.99"], g[f"{cc}_es0.99"].fillna(g["ew_es0.99"]))
            g[f"{col}_flag"] = f
            variants.append(("Switch (capped)", f"90th percentile ≥ 1, cap ξ ≤ {c}", col))
        for meth, setting, col in variants:
            s, e = capital_terms(g, col, "es0.99")
            err = _err(g, col, "es0.99")
            rows.append({"set": setname, "method": meth, "setting": setting, "rmse": _cell_rmse(g, col, "es0.99"),
                         "too_low_20": 100 * float((err < -0.2).mean()),
                         "flagged_%": 100 * float(g[f"{col}_flag"].mean()) if f"{col}_flag" in g else np.nan,
                         "worst_relative_cost": max((l * s + e) / best[l] for l in lambdas)})
    return pd.DataFrame(rows)


def oos_inference(frames=None, level=0.99, B=10000, seed=20240601):
    """Sampling uncertainty of the out-of-sample FZ0 comparison: Diebold-Mariano tests against EW
    (Newey-West variance), bootstrap 90% intervals for the mean difference (pairs of years
    resampled with replacement) and the share of bootstrap draws in which each method has the
    lowest mean loss."""
    frames = data_frames() if frames is None else frames
    M = ["ew", "median", "screen", "cap", "pen", "penk", "chw", "tpw", "eqd", "nbma"]
    rng = np.random.default_rng(seed)
    rows = []
    for nm, (t, smp) in frames.items():
        ms = [m for m in M if f"{m}_es0.99" in t and not t[f"{m}_es0.99"].isna().all()]
        sc = oos_scores(t, smp, ms, levels=(level,)).set_index("method")["scores"]
        S = np.array([np.asarray(sc[m], dtype=float) for m in ms])          # methods x pairs
        T = S.shape[1]
        idx = rng.integers(0, T, (B, T))
        boot = np.nanmean(S[:, idx], axis=2)                               # methods x B
        best = np.nanargmin(boot, axis=0)
        for i, m in enumerate(ms):
            dlt = S[i] - S[ms.index("ew")]
            _, md, p = nw_dm(dlt)
            bd = boot[i] - boot[ms.index("ew")]
            rows.append({"data": nm, "method": m, "pairs": T, "diff_vs_ew": float(np.nanmean(dlt)),
                         "ci_lo": float(np.nanquantile(bd, 0.05)), "ci_hi": float(np.nanquantile(bd, 0.95)),
                         "dm_p": p, "share_best": float(np.mean(best == i))})
    return pd.DataFrame(rows)


def identification_and_calibration_tables():
    """Identification (profile likelihood), calibration of the shape check, bootstrap size,
    threshold correlation, out-of-sample inference and the designs near the boundary."""
    d, nd = stress_frame(), new_design_frame()
    sens, lr = run_sensitivity(), run_lr()
    rows = []
    for nm, g in (("main", d), ("additional", nd)):
        g = g.merge(sens, on=["scenario", "n", "rep"], how="left", suffixes=("", "_s")).merge(lr, on=["scenario", "n", "rep"])
        e = _err(g, "tpw", "es0.99")
        big = (e.abs() > 0.5).values
        def ev(f, lab):
            rm = lambda m: 100 * np.sqrt(np.nanmean(e[m] ** 2))
            rows.append({"set": nm, "check": lab, "flagged_%": 100 * f.mean(), "tpw_rmse_flagged": rm(f), "tpw_rmse_unflagged": rm(~f),
                         "recall_%": 100 * (f & big).sum() / big.sum(), "precision_%": 100 * (f & big).sum() / max(f.sum(), 1)})
        for q in (80, 90, 95):
            for lev in (0.9, 1.0, 1.1):
                ev((g[f"xi_U{q}_mid"] >= lev).values, f"{q}th percentile ≥ {lev}")
        ev((g.lr_xi1 < 2.706).values, "LR test of ξ = 1 not rejected at 10%")
    save_table(pd.DataFrame(rows), "check_calibration")
    save_table(run_bound_B(), "shape_bound_bootstrap_size")
    save_table(run_threshold_correlation(), "threshold_correlation")
    frames = data_frames()
    save_table(oos_inference(frames), "out_of_sample_inference")
    lrd = []
    for nm, (t, smp) in frames.items():
        for i, (lab, x) in enumerate(smp):
            s, xi = lr_xi1(np.asarray(x, dtype=float))
            lrd.append({"data": nm, "sample": lab, "full": i == 0, "lr": s, "xi": xi})
    save_table(pd.DataFrame(lrd), "identification_lr_data")
    n4 = run_new4_designs()
    n4 = fill_fallbacks(n4, [m for m in METHODS if f"{m}_es0.99" in n4])
    save_table(table_by_design(n4, "es0.99", methods=FAM), "by_design_es99_boundary")
    M = [("ew", "EW"), ("median", "Median"), ("screen", "Screened"), ("cap", "Capped"), ("pen", "Penalized"), ("penk", "Pen-k"), ("chw", "BR-Hill"), ("tpw", "TPW")]
    rows = []
    for des in n4.scenario.unique():
        g = n4[n4.scenario == des]
        for meas in ("es0.975", "es0.99", "var0.999"):
            r = {"design": des, "measure": meas}
            for m, lab in M:
                r[lab] = f"{_cell_rmse(g, m, meas):.1f} ({100 * np.nanmedian(_err(g, m, meas)):+.1f})"
            rows.append(r)
    save_table(pd.DataFrame(rows), "boundary_designs_accuracy")

