FAMILY_LINES = [("ew", INK, "o", "-", "Equal weights"), ("median", AQUA, "D", "-.", "Median across thresholds"),
                ("pen", BLUE, "s", "--", "Penalized likelihood"), ("tpw", ORANGE, "^", "-", "TPW")]


def figure_real(t, name, ylabel, scale=1.0, yticks=None):
    """Annual ES 99% (log scale) of a loss data set for four methods; row 0 of t is the full
    sample, shown as a dashed line for TPW. Saved as PDF, SVG, EPS and 600-dpi PNG."""
    plt.rcParams.update(STYLE)
    full, yr = t.iloc[0], t.iloc[1:].copy()
    yr["year"] = yr["sample"].astype(int)
    fig, ax = plt.subplots(figsize=(6.6, 3.2))
    for m, col, mk, ls, lab in FAMILY_LINES:
        ax.plot(yr.year, yr[f"{m}_es0.99"].fillna(yr["ew_es0.99"]) * scale, color=col, marker=mk, ls=ls, lw=1.5,
                ms=4.2, label=lab)
    if "emp_es0.99" in yr:
        ax.plot(yr.year, yr["emp_es0.99"] * scale, ls="none", marker="x", ms=5, color=GREY, mew=1.2,
                label="Empirical ES (top 1% of claims)")
    ax.axhline(full["tpw_es0.99"] * scale, color=ORANGE, lw=0.8, ls=(0, (2, 2)))
    ax.text(yr.year.max() + 0.35, full["tpw_es0.99"] * scale * 1.06, "full-sample\nTPW", va="bottom", fontsize=7,
            color="#52514e")
    ax.set_yscale("log")
    step = 1 if len(yr) <= 12 else 2
    ax.set_xticks(yr.year[::step])
    ax.set_xlim(yr.year.min() - 0.4, yr.year.max() + 2.2)
    if yticks is not None:
        ax.set_yticks(yticks)
        ax.set_yticklabels([f"{v:,.0f}" for v in yticks])
    ax.set_ylabel(ylabel)
    ax.legend(loc="upper center", ncol=3, fontsize=7.5, bbox_to_anchor=(0.5, 1.2))
    out = _save(fig, name)
    return out



BIG = dict(STYLE, **{"font.size": 10.5, "axes.titlesize": 11, "legend.fontsize": 9.5})


def figure_precision_profile(profile, designs=("GPD xi=0.5", "Regime shuffled"),
                      titles=("(a) GPD, ξ = 0.5", "(b) Calm/crisis mixture"), n=500, name="precision_profile"):
    """Relative bootstrap SE by threshold and target (median over samples, log scale), with the
    interquartile range for ES 99% and the thresholds with fewer than 25 exceedances shaded."""
    from matplotlib.ticker import FixedLocator, FixedFormatter, NullLocator
    plt.rcParams.update(BIG)
    col = "design" if "design" in profile else "scenario"
    fig, axs = plt.subplots(1, 2, figsize=(7.2, 3.9), sharey=True)
    handles = None
    for ax, sc, title in zip(axs, designs, titles):
        g = profile[profile[col] == sc]
        for meas, c, ls, mk, lab in [("var0.99", GREY, "-", "o", "VaR 99%"), ("var0.999", BLUE, "--", "s", "VaR 99.9%"),
                                     ("es0.975", ORANGE, "-", "^", "ES 97.5%"), ("es0.99", AQUA, "-", "D", "ES 99%")]:
            s = g[g.measure == meas].groupby("q")["relSE"]
            ax.plot(s.median().index, s.median().values, color=c, ls=ls, lw=2.2 if meas.startswith("es") else 1.4,
                    marker=mk, ms=4, label=lab + " (median)")
            if meas == "es0.99":
                ax.fill_between(s.median().index, s.quantile(0.25).values, s.quantile(0.75).values, color=c, alpha=0.12,
                                lw=0, label="ES 99%: interquartile range")
        ax.axvspan(0.9505, 0.975, color="#ece9e2", alpha=0.8, lw=0, zorder=0)
        ax.text(0.962, 0.03, "k < 25", transform=ax.get_xaxis_transform(), ha="center", fontsize=9, color="#52514e")
        ax.set_yscale("log")
        ax.yaxis.set_major_locator(FixedLocator([0.1, 0.2, 0.5, 1, 2, 5]))
        ax.yaxis.set_major_formatter(FixedFormatter(["0.1", "0.2", "0.5", "1", "2", "5"]))
        ax.yaxis.set_minor_locator(NullLocator())
        ax.set_ylim(0.1, 8)
        ax.set_title(title, loc="left")
        ax.set_xlabel("Threshold quantile level q")
        sec = ax.secondary_xaxis("top", functions=(lambda q: n * (1 - q), lambda k: 1 - k / n))
        sec.set_xticks([75, 50, 25, 15])
        sec.set_xlabel(f"Exceedances k (n = {n})", fontsize=9)
        handles = ax.get_legend_handles_labels()
    axs[0].set_ylabel("Bootstrap SE / true value")
    fig.legend(*handles, loc="lower center", ncol=3, fontsize=9, bbox_to_anchor=(0.5, -0.01))
    fig.tight_layout(rect=(0, 0.1, 1, 1))
    out = figure_dir()
    for ext in ("pdf", "svg", "eps"):
        fig.savefig(out / f"{name}.{ext}")
    fig.savefig(out / f"{name}.png", dpi=600)
    plt.close(fig)
    return out / f"{name}.png"


def figure_shapes(samples, title_map, name="fitted_shapes", qs=None):
    """Fitted GPD shape at each threshold of the grid for selected loss samples (dict name -> losses)."""
    qs = QS if qs is None else qs
    plt.rcParams.update(BIG)
    k = len(samples)
    fig, axs = plt.subplots(1, k, figsize=(7.2, 2.9), sharey=True)
    axs = np.atleast_1d(axs)
    for ax, (nm, x) in zip(axs, samples.items()):
        x = np.asarray(x, dtype=float)
        u = np.quantile(x, qs)
        xi = [fit_gpd(x[x > v] - v).xi for v in u]
        ax.axhspan(0.9, 2.6, color="#f3d9cf", alpha=0.55, lw=0)
        ax.axhline(1.0, color=ORANGE, lw=0.9, ls="--")
        ax.plot(qs, xi, color=INK, marker="o", ms=3.5, lw=1.4)
        ax.set_title(title_map.get(nm, nm), loc="left", fontsize=10)
        ax.set_xticks([0.85, 0.91, 0.97])
        ax.set_xlabel("q")
    axs[0].set_ylabel("Fitted shape ξ̂")
    axs[0].set_ylim(-0.6, 2.4)
    axs[0].text(0.86, 1.95, "ξ̂ ≥ 0.9", fontsize=8.5, color="#7a3b22")
    return _save(fig, name)


def figure_flowchart(bmin=200, name="decision_flowchart"):
    """Decision framework for a threshold-averaged ES."""
    from matplotlib.patches import FancyBboxPatch
    plt.rcParams.update(BIG)
    fig, ax = plt.subplots(figsize=(7.2, 6.4))
    ax.set_xlim(0, 10); ax.set_ylim(0, 10); ax.axis("off")

    def box(x, y, w, h, text, fc="#f2f2f2", ec="#333333", bold=False):
        ax.add_patch(FancyBboxPatch((x - w / 2, y - h / 2), w, h, boxstyle="round,pad=0.08", fc=fc, ec=ec, lw=1.0))
        ax.text(x, y, text, ha="center", va="center", fontsize=8.3, fontweight="bold" if bold else "normal", wrap=True)

    def arrow(x0, y0, x1, y1, label=None, dx=0.15, dy=0.0):
        ax.annotate("", xy=(x1, y1), xytext=(x0, y0), arrowprops=dict(arrowstyle="-|>", lw=0.9, color="#333333"))
        if label:
            ax.text((x0 + x1) / 2 + dx, (y0 + y1) / 2 + dy, label, fontsize=8, style="italic")

    box(3.4, 9.35, 5.6, 0.75, "Tail measure from a short loss sample,\nthreshold grid q = 0.85, ..., 0.97", bold=True)
    box(3.4, 7.95, 5.6, 0.8, "1. Is the target VaR at 99.5% or below?")
    box(8.4, 7.95, 2.7, 0.8, "Any threshold average;\nequal weights suffice", fc="#e8f1e8")
    box(3.4, 6.45, 5.6, 0.95, f"2. Identification check: 90th percentile of the\nbootstrap shape at q = 0.91 (B ≥ {bmin}) ≥ 1?")
    box(8.4, 6.45, 2.7, 1.55, "ES weakly identified:\nreport the range of\nprotected estimates and\nthe empirical ES; treat the\nrange as model risk", fc="#f8e6e3")
    box(3.4, 4.85, 5.6, 0.95, "3. Do extremes cluster (extremal index\nwell below 1, e.g. daily returns)?")
    box(8.4, 4.85, 2.7, 0.95, "Filter (GARCH) or decluster\nfirst; do not use TPW", fc="#fff4dc")
    box(3.4, 3.25, 5.6, 0.95, "4. Cost of under-capitalization relative to\nover-capitalization (λ)")
    box(1.75, 1.45, 3.1, 1.05, "λ close to 1:\npenalized likelihood\n(check against empirical ES)", fc="#e8eef8")
    box(5.95, 1.45, 3.6, 1.05, "λ above about 3-5:\ncapped shape (ξ ≤ 0.8) or TPW\n(TPW only for moderately heavy tails)", fc="#e8eef8")
    arrow(3.4, 8.97, 3.4, 8.37)
    arrow(6.2, 7.95, 7.05, 7.95, "yes", dx=-0.25, dy=0.12)
    arrow(3.4, 7.55, 3.4, 6.93, "no")
    arrow(6.2, 6.45, 7.05, 6.45, "yes", dx=-0.25, dy=0.12)
    arrow(3.4, 5.97, 3.4, 5.33, "no")
    arrow(6.2, 4.85, 7.05, 4.85, "yes", dx=-0.25, dy=0.12)
    arrow(3.4, 4.37, 3.4, 3.73, "no")
    arrow(2.6, 2.77, 1.9, 1.98)
    arrow(4.2, 2.77, 5.4, 1.98)
    _save(fig, name)
    plt.close(fig)
    return figure_dir() / f"{name}.png"


def figure_profile(samples, name="es_profile_likelihood", q=0.91, alpha=0.99):
    """Profile likelihood-ratio statistic of the ES at one threshold, with its limit 2(l_hat - l_1)
    and the 90% critical value, for a few loss samples (dict label -> losses)."""
    plt.rcParams.update(BIG)
    k = len(samples)
    fig, axs = plt.subplots(1, k, figsize=(7.2, 2.7), sharey=True)
    axs = np.atleast_1d(axs)
    for ax, (lab, x) in zip(axs, samples.items()):
        x = np.asarray(x, dtype=float)
        u = np.quantile(x, q)
        y = x[x > u] - u
        p = y.size / x.size
        f = fit_gpd(y)
        e_hat = pot_es(u, f, p, alpha)
        grid = np.geomspace(u * 1.02, max(1e4, 100 * e_hat), 120)
        prof, lmax, l1, _ = profile_es(y, u, p, alpha, grid)
        lr = 2 * (lmax - prof)
        ax.plot(grid, lr, color="#1f4e79", lw=1.6)
        ax.axhline(2.706, color="#b03a2e", ls="--", lw=1.0)
        ax.axhline(2 * (lmax - l1), color="#555555", ls=":", lw=1.2)
        ax.axvline(e_hat, color="#555555", lw=0.6)
        ax.set_xscale("log")
        ax.set_ylim(0, 12)
        ax.set_title(f"{lab} (k = {y.size})")
        ax.set_xlabel("ES 99%")
    axs[0].set_ylabel("Likelihood-ratio statistic")
    fig.tight_layout()
    _save(fig, name)
    plt.close(fig)
    return figure_dir() / f"{name}.png"

# ==========================================================================================
# R SCRIPTS
# ==========================================================================================
R_SOURCE = r"""# Competitors on the exported stress samples:
#  (1) Northrop, Attalides & Jonathan (2017) Bayesian leave-one-out threshold selection (threshr):
#      'nbest' = predictive from the best training threshold; 'nbma' = predictive averaged over
#      thresholds with the posterior threshold weights (their eq. 15), validation threshold = top.
#  (2) Bader, Yan & Zhang (2018) ForwardStop on Anderson-Darling p-values (eva), MLE at the chosen threshold.
suppressMessages({library(threshr); library(eva)}); options(warn = -1); set.seed(14)
# Usage:  Rscript R/r_benchmarks.R <sample folder> <output csv> [part] [nparts]
#   e.g.  Rscript R/r_benchmarks.R outputs/cache/full/rcomp outputs/cache/full/rcomp_out/part0.csv
# The folder holds index.csv (scenario, n, rep, file) and one CSV per sample (column x),
# written by export_rcomp_samples() or export_danish_samples().
# Packages: threshr (>= 1.0.8) and eva (>= 0.2.7).
args <- commandArgs(TRUE); folder <- args[1]; out_file <- args[2]
part <- if (length(args) >= 3) as.integer(args[3]) else 0L
nparts <- if (length(args) >= 4) as.integer(args[4]) else 1L
idx <- read.csv(file.path(folder, "index.csv"))
QS <- seq(0.85, 0.97, by = 0.01); LV <- c(0.975, 0.99, 0.995, 0.999); LE <- c(0.975, 0.99)
S_tail <- function(x, u, p, s, xi) {        # survival P(X > x), x >= u, for draw vectors
  z <- pmax(1 + xi * (x - u) / s, 0)
  ifelse(abs(xi) < 1e-8, p * exp(-(x - u) / s), p * z^(-1 / xi))
}
pred <- function(draws, a) {               # draws: list of data frames (u,p,s,xi,w) ; mixture predictive
  f <- function(x) sum(sapply(draws, function(d) d$w[1] * mean(S_tail(x, d$u, d$p, d$s, d$xi)))) - (1 - a)
  lo <- max(sapply(draws, function(d) d$u[1])); hi <- lo + 1
  if (f(lo) < 0) return(NA)
  k <- 0; while (f(hi) > 0 && k < 200) { hi <- lo + 2 * (hi - lo); k <- k + 1 }
  uniroot(f, c(lo, hi), tol = 1e-8)$root
}
pred_es <- function(draws, a, q) {         # q + E[(X - q)+] / (1 - a), draws with xi >= 1 dropped
  if (!is.finite(q)) return(NA)
  m <- sum(sapply(draws, function(d) { ok <- d$xi < 1
    d$w[1] * sum(S_tail(q, d$u[ok], d$p[ok], d$s[ok], d$xi[ok]) * (d$s[ok] + d$xi[ok] * (q - d$u[ok])) / (1 - d$xi[ok])) / nrow(d) }))
  q + m / (1 - a)
}
rows <- list()
for (i in which((seq_len(nrow(idx)) - 1) %% nparts == part)) {
  x <- read.csv(file.path(folder, idx$file[i]))$x; n <- length(x)
  u_vec <- unname(quantile(x, QS, type = 7))
  out <- data.frame(scenario = idx$scenario[i], n = idx$n[i], rep = idx$rep[i])
  t0 <- Sys.time()
  r <- tryCatch({
    fit <- suppressWarnings(ithresh(x, u_vec = u_vec, n = 2000))
    M <- length(u_vec); N <- fit$n
    ptw <- threshr:::post_thresh_weights(x = fit, which_v = 1, u_prior = rep(1, M))
    best <- which.max(fit$pred_perf[, 1])
    dr <- lapply(seq_along(ptw), function(j) { rr <- (1 + (j - 1) * N):(j * N)
      data.frame(u = u_vec[j], p = fit$sim_vals[rr, 1], s = fit$sim_vals[rr, 2], xi = fit$sim_vals[rr, 3], w = ptw[j]) })
    db <- dr[best]; db[[1]]$w <- 1
    for (a in LV) { out[[paste0("nbest_var", a)]] <- pred(db, a); out[[paste0("nbma_var", a)]] <- pred(dr[ptw > 1e-6], a) }
    for (a in LE) { out[[paste0("nbest_es", a)]] <- pred_es(db, a, out[[paste0("nbest_var", a)]])
                    out[[paste0("nbma_es", a)]] <- pred_es(dr[ptw > 1e-6], a, out[[paste0("nbma_var", a)]]) }
    out$nbest_q <- QS[best]; out$nbma_Neff <- 1 / sum(ptw^2); TRUE
  }, error = function(e) { out$nerr <<- conditionMessage(e); FALSE })
  out$nsec <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
  r2 <- tryCatch({
    st <- tryCatch(gpdSeqTests(x, thresholds = u_vec, method = "ad"),
                   error = function(e) { out$fstop_boot <<- TRUE; gpdSeqTests(x, thresholds = u_vec, method = "ad", nsim = 199) })
    k <- suppressWarnings(max(which(st$ForwardStop <= 0.05)))
    j <- if (!is.finite(k)) 1 else min(k + 1, nrow(st))
    s <- st$est.scale[j]; xi <- st$est.shape[j]; u <- u_vec[j]; p <- st$num.above[j] / n
    for (a in LV) out[[paste0("fstop_var", a)]] <- u + s / xi * ((p / (1 - a))^xi - 1)
    for (a in LE) { v <- out[[paste0("fstop_var", a)]]; out[[paste0("fstop_es", a)]] <- if (xi < 1) (v + s - xi * u) / (1 - xi) else NA }
    out$fstop_q <- QS[j]; TRUE
  }, error = function(e) { out$ferr <<- conditionMessage(e); FALSE })
  rows[[length(rows) + 1]] <- out
  if (length(rows) %% 20 == 0) cat(part, length(rows), format(Sys.time()), "\n")
}
all <- do.call(function(...) Reduce(function(a, b) merge(a, b, all = TRUE), list(...)), rows)
dir.create(dirname(out_file), showWarnings = FALSE, recursive = TRUE)
write.csv(all, out_file, row.names = FALSE)
"""



EQD_SOURCE = r"""# Expected quantile discrepancy (EQD) threshold selection of Murphy, Tawn and Varty (2025, Technometrics),
# as implemented in the R package mev (>= 2.2, function thselect.vmetric, type = "eqd",
# defaults B = 199, L1 distance, nonparametric bootstrap), on the grid of 13 thresholds.
# VaR and ES from the GPD maximum likelihood fit at the selected threshold.
# Usage: Rscript R/eqd.R <sample folder with index.csv> <output csv> [part] [nparts]
suppressMessages(library(mev)); options(warn = -1); set.seed(2024)
args <- commandArgs(TRUE); folder <- args[1]; out_file <- args[2]
part <- if (length(args) >= 3) as.integer(args[3]) else 0L
nparts <- if (length(args) >= 4) as.integer(args[4]) else 1L
idx <- read.csv(file.path(folder, "index.csv"))
QS <- seq(0.85, 0.97, by = 0.01); LV <- c(0.975, 0.99, 0.995, 0.999); LE <- c(0.975, 0.99)
rows <- list()
for (i in which((seq_len(nrow(idx)) - 1) %% nparts == part)) {
  x <- read.csv(file.path(folder, idx$file[i]))$x; n <- length(x)
  u_vec <- unname(quantile(x, QS, type = 7))
  out <- data.frame(scenario = idx$scenario[i], n = idx$n[i], rep = idx$rep[i])
  t0 <- Sys.time()
  ok <- tryCatch({
    r <- thselect.vmetric(xdat = x, thresh = u_vec, type = "eqd")
    j <- which.min(r$metric); u <- u_vec[j]; s <- r$scale[j]; xi <- r$shape[j]; p <- mean(x > u)
    for (a in LV) out[[paste0("eqd_var", a)]] <- if (abs(xi) < 1e-8) u - s * log((1 - a) / p) else u + s / xi * (((1 - a) / p)^(-xi) - 1)
    for (a in LE) { v <- out[[paste0("eqd_var", a)]]; out[[paste0("eqd_es", a)]] <- if (xi < 1) (v + s - xi * u) / (1 - xi) else NA }
    out$eqd_q <- QS[j]; out$eqd_xi <- xi; TRUE
  }, error = function(e) { out$eqd_err <<- conditionMessage(e); FALSE })
  out$nsec <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
  rows[[length(rows) + 1]] <- out
  if (length(rows) %% 25 == 0) cat(part, length(rows), format(Sys.time()), "\n")
}
all <- do.call(function(...) Reduce(function(a, b) merge(a, b, all = TRUE), list(...)), rows)
dir.create(dirname(out_file), showWarnings = FALSE, recursive = TRUE)
write.csv(all, out_file, row.names = FALSE)
"""


def write_r_scripts():
    """Write the R benchmark script and the EQD script to R/."""
    R_SCRIPT.parent.mkdir(parents=True, exist_ok=True)
    R_SCRIPT.write_text(R_SOURCE, encoding="utf-8")
    (R_SCRIPT.parent / "eqd.R").write_text(EQD_SOURCE, encoding="utf-8")
    return R_SCRIPT.parent

# ==========================================================================================
# ANALYSIS STEPS
# ==========================================================================================
"""One function per analysis step. Each step computes (or loads from the cache) its results,
writes its tables to outputs/tables/<mode>/ and returns them as a dict. Steps can be run in any
order; a step that needs results of another computes them (or reads them from the cache)."""
import shutil
import subprocess

import numpy as np
import pandas as pd

STD_METHODS = ["single", "ew", "cv", "cv_loo", "vpw", "tpw_core", "tpw", "tmv"]


def _save_all(out, index_keys=()):
    for k, v in out.items():
        if isinstance(v, (pd.DataFrame, pd.Series)):
            save_table(v, k, index=k in index_keys)
    return out


def _stress_filled():
    s = run_stress()
    return fill_fallbacks(s[s["ok"].astype(bool)].copy(), STD_METHODS)


def move_outdated_caches():
    """Move cached result files that lack columns produced by the current estimators (for example
    files written by an older version of this code) to outputs/cache/<mode>/_outdated/, so that
    they are recomputed. Nothing is deleted."""
    target_root = cache_dir() / "_outdated"
    moved = []
    for p in cache_dir().rglob("*.csv"):
        if target_root in p.parents:
            continue
        try:
            cols = pd.read_csv(p, nrows=0).columns
        except Exception:
            continue
        if "ew_es0.99" in cols and "median_es0.99" not in cols:
            target = target_root / p.relative_to(cache_dir())
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(p), str(target))
            moved.append(str(p.relative_to(cache_dir())))
    if moved:
        log(f"moved {len(moved)} outdated cache file(s) to {target_root}")
    return moved


# ----------------------------------------------------------------------------------------
# Steps
# ----------------------------------------------------------------------------------------
def step_data_check():
    """Load (or download and archive) every data set and summarize it."""
    sp, panel = market_series()
    rows = [{"series": "S&P 500 (log losses)", "n": len(sp), "first": sp.index.min().date(), "last": sp.index.max().date()}]
    rows += [{"series": a, "n": len(l), "first": l.index.min().date(), "last": l.index.max().date(),
              "sha256 of snapshot": sha256_file(CLEAN_DIR / f"{a}_clean.csv")[:16]} for a, l in panel.items()]
    dan = load_danish()
    rows.append({"series": "Danish fire losses", "n": len(dan), "first": dan.date.min().date(), "last": dan.date.max().date()})
    return {"data_summary": pd.DataFrame(rows)}


def step_precision_theory():
    """Asymptotic precision of each threshold, probability of near-singular fits, finite-sample
    precision dispersion and the precision-profile figure."""
    t1 = asymptotic_dispersion_table()
    t2 = cached_csv(cache_dir() / f"explode_R{EXPLODE_R}.csv", near_singular_probability_table)
    prof = cached_csv(cache_dir() / f"se_profile_R{PROFILE_R}_n{PROFILE_N}_B{PROFILE_B}.csv", se_profile)
    out = {"asymptotic_dispersion": t1.pivot(index="xi", columns="target", values="D0")[
               ["VaR 97.5%", "VaR 99%", "VaR 99.5%", "VaR 99.9%", "ES 97.5%", "ES 99%"]],
           "near_singular_probability": t2,
           "finite_sample_dispersion": finite_sample_dispersion_table(prof)}
    _save_all(out, index_keys=("asymptotic_dispersion", "finite_sample_dispersion"))
    out["fig_precision_profile"] = figure_precision_profile(prof, name="precision_profile")
    return out


def step_weighting_simulation():
    """Accuracy of the threshold-weighting schemes on the stress designs and exact GPD samples."""
    s = prepare(run_stress())
    g = prepare(run_gpd())
    acc_s, acc_g = accuracy(s, ["scenario", "n"]), accuracy(g, ["xi", "n"])
    out = {"weighting_accuracy_by_target": weighting_accuracy_table(acc_s),
           "weighting_es975_n250_by_design": es975_by_design_table(s),
           "weighting_shortfall_excess": shortfall_excess_table(acc_s),
           "weighting_failure_rates": failure_rate_table(s),
           "weighting_exact_gpd_es": exact_gpd_es_table(g),
           "tpw_bias_term_versions": bias_term_versions_table(acc_s, acc_g),
           "weighting_reliability_summary": reliability(s).to_frame("value"),
           "accuracy_all_stress": acc_s, "accuracy_all_gpd": acc_g}
    _save_all(out, index_keys=("weighting_es975_n250_by_design", "weighting_failure_rates", "weighting_exact_gpd_es",
                               "weighting_reliability_summary"))
    out["fig_weighting_accuracy"] = figure_weighting_accuracy(acc_s)
    out["stress"] = s
    return out


def step_weighting_robustness():
    """Threshold grids, block bootstrap and bootstrap size; robust combiners; near-singular rate by k."""
    t = robustness_table(run_robustness())
    stress = _stress_filled()
    f = robust_combiners_table(stress.drop(columns=[c for c in stress if c.startswith("true_")]), run_robust_combiners())
    rate = cached_csv(cache_dir() / "explosion_rate_check.csv", explosion_rate_check)
    return _save_all({"weighting_robustness": t, "robust_combiners_comparison": f, "near_singular_rate_by_k": rate})


def step_protections():
    """The family of protections (median, screening, capped shape, penalized likelihood,
    bias-reduced Hill, TPW): accuracy, results by design, flagged samples, TPW-median gap,
    alternative caps, exact GPD samples and capital costs."""
    d = prepare_stress(_stress_filled(), run_robust_combiners(), run_extra_stress())
    g = run_gpd()
    g = fill_fallbacks(g[g["ok"].astype(bool)].copy(), STD_METHODS)
    eg = run_extra_gpd()
    g = (g.drop(columns=[c for c in g if c.startswith(("median_", "trim20_", "screen_"))])
         .merge(run_robust_combiners_gpd(), on=["xi", "n", "rep"])
         .merge(eg.drop(columns=[c for c in eg if c.startswith("true_")]), on=["xi", "n", "rep"]))
    out = {"protections_accuracy": table_protection(d),
           "protections_by_design_es99": table_by_design(d, "es0.99"),
           "protections_by_design_var999": table_by_design(d, "var0.999"),
           "protections_by_design_es975": table_by_design(d, "es0.975"),
           "protections_ordinary_vs_flagged": table_ordinary(d),
           "tpw_median_gap": table_gap(d),
           "capped_shape_caps": table_caps(d),
           "protections_exact_gpd_es99": table_gpd(g, "es0.99"),
           "protections_exact_gpd_var999": table_gpd(g, "var0.999"),
           "capital_costs": table_capital(d), "capital_relative_costs": table_regret(d)}
    return _save_all(out)


def step_r_benchmarks(run_r=True, nparts=1):
    """Bayesian threshold averaging (threshr) and ForwardStop (eva) on the stress samples.
    Needs R; without it, stored results are used if present, otherwise the step is skipped."""
    rc = run_r_benchmarks("stress", nparts) if run_r else load_rcomp("stress")
    if rc is None:
        log("R benchmarks skipped: no R results available")
        return {}
    return _save_all({"r_benchmarks_stress": r_benchmark_table(prepare(run_stress()), rc)})


def step_market():
    """Market data: full-sample estimates and stability across stressed rolling windows."""
    lv, win = run_levels(), run_windows()
    out = {"market_levels": market_levels_table(lv),
           "stressed_windows_es99": stressed_windows_table(win, "es0.99"),
           "stressed_windows_es975": stressed_windows_table(win, "es0.975"),
           "stressed_windows_var999": stressed_windows_table(win, "var0.999"),
           "windows_largest_disagreement_es975": largest_disagreements(win, "es0.975")}
    return _save_all(out, index_keys=("market_levels",))


def step_backtests():
    """Rolling GARCH-EVT forecasts and ES backtests (the slowest step)."""
    fcs, bt, dm = run_backtests()
    return _save_all({"backtest_summary": backtest_summary_table(bt, dm), "backtests_by_series": bt, "dm_tests_fz0": dm})


def step_danish_weighting(run_r=True):
    """Danish fire losses: stability of the weighting schemes across years."""
    d = run_danish()
    rc = run_r_benchmarks("danish") if run_r else load_rcomp("danish")
    out = _save_all({"danish_weighting_stability": danish_stability_table(d, rc),
                     "danish_weighting_by_year": danish_by_year_table(d)})
    out["fig_danish_weighting"] = figure_danish_weighting(d)
    return out


def step_norwegian_nominal(run_r=True):
    """Norwegian fire claims in nominal terms: stability of the weighting schemes across years."""
    d = run_norwegian()
    rc = run_r_benchmarks("norwegian") if run_r else load_rcomp("norwegian")
    out = _save_all({"norwegian_nominal_stability": table_norwegian(d, rc),
                     "norwegian_nominal_by_year": table_norwegian_by_year(d)})
    out["fig_norwegian_nominal"] = figure_norwegian(d)
    return out


def step_insurance_protections(run_r=True):
    """Danish losses and Norwegian claims at 2012 prices with every protection: stability,
    empirical-ES check, capital range and figures."""
    ex = run_extra_real()
    dd = load_danish()
    dan = add_empirical(real_frame(run_danish(), ex, "danish"),
                        {"1980-1990": dd["loss"].values, **{str(y): g["loss"].values for y, g in dd.groupby("year")}})
    nr = dict(norfire_real_samples()[1])
    nor = add_empirical(real_frame(run_norfire_real(), ex, "norway_real"), nr)
    rc_d = run_r_benchmarks("danish") if run_r else load_rcomp("danish")
    rc_n = run_r_benchmarks("norfire_real") if run_r else load_rcomp("norfire_real")
    out = _save_all({"danish_protections": table_real(dan, rc_d), "norwegian_real_protections": table_real(nor, rc_n),
                     "danish_capital_range": table_capital_range(dan), "norwegian_capital_range": table_capital_range(nor),
                     "danish_protections_by_year": table_real_by_year(dan),
                     "norwegian_real_protections_by_year": table_real_by_year(nor)})
    out["fig_danish"] = figure_real(dan, "danish_protections_es99", "ES 99% (million DKK), log scale",
                                    yticks=[10, 20, 50, 100, 200, 500, 1000])
    out["fig_norway"] = figure_real(nor, "norwegian_protections_es99", "ES 99% (million NOK, 2012 prices), log scale",
                                    scale=1e-3, yticks=[50, 100, 200, 500, 1000])
    out["fig_shapes"] = figure_shapes(
        {"D1980": dd[dd.year == 1980]["loss"].values, "D1982": dd[dd.year == 1982]["loss"].values,
         "N1976": nr["1976"], "N1986": nr["1986"], "N1988": nr["1988"]},
        {"D1980": "Danish 1980", "D1982": "Danish 1982", "N1976": "Norway 1976", "N1986": "Norway 1986", "N1988": "Norway 1988"},
        name="fitted_shapes")
    return out


def step_near_singular_and_timing():
    """Probability of a near-singular fit as a function of the number of exceedances, for GPD and
    non-GPD tails, and run times of the methods."""
    R = 10000 if RUN_MODE == "full" else 200
    p = cached_csv(cache_dir() / f"near_singular_k_R{R}.csv", lambda: run_near_singular_k(R))
    out = {"near_singular_decay_slopes": pd.concat([slopes(p, x) for x in XI_STARS], ignore_index=True),
           "near_singular_probability_by_k": p, "run_times": run_timing()}
    return _save_all(out)


def _run_r_scripts():
    """EQD (mev) on the loss data and the stress samples, and the Bayesian scheme on the
    additional loss data, with Rscript."""
    rscript = find_rscript()
    if rscript is None:
        log("Rscript not found - EQD and Bayesian results from stored files if present")
        return
    cd = cache_dir() / "checks"
    eq = export_eqd_data()
    bn = cd / "bayes_new"
    bn.mkdir(parents=True, exist_ok=True)
    idx = pd.read_csv(eq / "index.csv")
    idx = idx[idx.scenario.isin(["French fire", "BMW", "Siemens"])]
    for f in idx.file:
        shutil.copy(eq / f, bn / f)
    idx.to_csv(bn / "index.csv", index=False)
    rcomp = export_rcomp_samples()
    for script, src, out in ((R_SCRIPT.parent / "eqd.R", eq, cd / "eqd_data_out"),
                             (R_SCRIPT.parent / "eqd.R", rcomp, cd / "eqd_stress_out"),
                             (R_SCRIPT, bn, cd / "bayes_new_out")):
        out.mkdir(parents=True, exist_ok=True)
        f = out / "part0.csv"
        if not f.exists():
            with open(out / "R_log.txt", "w") as logf:
                subprocess.run([rscript, str(script), str(src), str(f), "0", "1"], stdout=logf, stderr=subprocess.STDOUT)


def step_reliability_and_identification(run_r=True):
    """Reliability checks, additional designs and loss data, out-of-sample scores, dynamic
    forecasts, sensitivity of the constants, extremal index, identification analysis and the
    profile-likelihood and decision-framework figures."""
    if run_r:
        _run_r_scripts()
    run_reliability_analysis()
    dd = load_danish()
    out = {"fig_profile": figure_profile({"Danish 1980": dd[dd.year == 1980]["loss"].values,
                                          "Danish 1987": dd[dd.year == 1987]["loss"].values,
                                          "Danish 1980-1990": dd["loss"].values}, name="es_profile_likelihood"),
           "fig_flowchart": figure_flowchart(100, name="decision_flowchart")}
    st = r_results("eqd_stress_out", "eqd_stress_results.csv")
    if st is not None:
        out.update(_save_all({"eqd_stress": eqd_stress_table(st)}))
    return out


def step_summary(results):
    """Integrity checks over the steps that were run, and the manifest."""
    checks = {"no warnings recorded": len(WARNINGS) == 0}
    sim = results.get("weighting_simulation")
    if sim is not None:
        checks["all simulation replications succeeded"] = bool(sim["stress"]["ok"].all())
    checks["steps completed"] = ", ".join(results) if results else "none"
    path = write_manifest({"steps": list(results)})
    log(f"manifest: {path}")
    return pd.Series(checks, name="result"), path

