# out-of-sample FZ0 scores on the following 21 days; one summary table for all data sets.
# Uses the functions defined earlier in the notebook. Results are cached in outputs/cache/<mode>/windows/,
# tables are saved to outputs/tables/<mode>/.
# =========================================================================================
_needed = ["market_series", "run_windows", "run_levels", "extra_estimates", "estimate_all", "empirical_es", "fit_gpd",
           "fit_garch_t", "standardized_losses", "_sigma2_path", "fz0", "nw_dm", "cached_csv", "pmap", "cache_dir",
           "table_dir", "_slug", "_lim", "_save_all", "log", "QS", "J_MID", "ASSETS", "ASSET_NAMES", "WIN_LEN", "WIN_STEP",
           "WIN_B", "WIN_MAX"]
_missing = [n for n in _needed if n not in globals()]
if _missing:
    raise NameError("Run all the earlier cells of the notebook first; not defined yet: " + ", ".join(_missing))
RESULTS = globals().get("RESULTS", {})

"""Market data across sample regimes.

The rolling one-year windows of the six market series (250 days, moved forward by 21 days) get
the same treatment as the annual insurance samples:
  * every protection (median, screened EW, capped shape, penalized likelihood, bias-reduced Hill)
    next to the weighting schemes, and the shape-bound check (90th percentile of the bootstrap
    shape at q = 0.91, drawn from the same resamples as the window's TPW bootstrap);
  * stability (ratio to the same method's full-sample estimate, change between consecutive
    windows), the empirical check (estimate below the window's empirical ES) and out-of-sample
    FZ0 scores on the losses of the following 21 days, with Diebold-Mariano tests against EW;
  * the same analysis on GARCH(1,1)-t filtered residuals of each window (the tail of the
    standardized losses, and one-step conditional forecasts for the following 21 days).
A final table summarizes every data set by sample regime (long samples, one-year windows,
annual loss samples)."""
import warnings

MKT_METHODS = ["ew", "cv", "vpw", "median", "screen", "cap", "pen", "chw", "tpw"]
MKT_LABELS = {"ew": "Equal weights", "cv": "CV-BMA", "vpw": "VPW", "median": "Median", "screen": "Screened EW",
              "cap": "Capped shape", "pen": "Penalized", "chw": "BR-Hill", "tpw": "TPW"}
PROTECTED = ["median", "screen", "cap", "tpw"]            # the protections that neither under- nor overshoot
OOS_LEVELS = (0.975, 0.99)
FILTER_SEED_SHIFT = 500000                               # seeds of the filtered windows: window seed + shift


def window_series():
    """The six series of the rolling windows: S&P 500 log losses and the panel without its S&P 500."""
    sp, panel = market_series()
    return {"S&P 500": sp, **{k: v for k, v in panel.items() if k != "SP500"}}


def _ends(L):
    return list(range(WIN_LEN, len(L) + 1, WIN_STEP))[:WIN_MAX]


def _window_seed(i, j):
    return 140000 + 1000 * i + j                         # as in run_windows: same bootstrap resamples


def shape_bound(x, rng, B, qs=QS):
    """Fitted shape at the middle threshold (q = 0.91) and the 90th percentile of its bootstrap
    distribution, threshold held fixed. rng draws the resamples exactly as bootstrap_reps."""
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    n = x.size
    um = np.quantile(x, qs)[J_MID]
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        f = fit_gpd(x[x > um] - um)
        xis = np.full(B, np.nan)
        for b in range(B):
            xb = x[rng.integers(0, n, n)]
            fb = fit_gpd(xb[xb > um] - um)
            if fb.ok:
                xis[b] = fb.xi
    return {"xi_mid": float(f.xi) if f.ok else np.nan,
            "xi_U90_mid": float(np.nanquantile(xis, 0.9)) if np.isfinite(xis).any() else np.nan}


def _with_fallback(df, meas, methods=MKT_METHODS):
    """Windows x methods matrix of one measure; TPW -> TPW-core -> EW, any other gap -> EW."""
    M = pd.DataFrame({m: df[f"{m}_{meas}"] if f"{m}_{meas}" in df else np.nan for m in methods}, index=df.index)
    if f"tpw_core_{meas}" in df and "tpw" in M:
        M["tpw"] = M["tpw"].fillna(df[f"tpw_core_{meas}"])
    return M.apply(lambda c: c.fillna(M["ew"]))


# ----------------------------------------------------------------------------------------
# Unconditional windows: protections, shape bound and empirical ES
# ----------------------------------------------------------------------------------------
def _window_extra(end, x, seed, B):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        out = {"end": end}
        out.update(extra_estimates(x))
        out.update(shape_bound(x, np.random.default_rng(seed), B))
        out.update({f"emp_es{a}": empirical_es(x, a) for a in OOS_LEVELS})
    return out


def run_window_protections():
    """{series: frame indexed by window end} with every weighting scheme (from run_windows), every
    protection, the shape bound and the empirical ES of the window."""
    base = run_windows()
    out = {}
    for i, (name, losses) in enumerate(window_series().items()):
        L = losses.dropna()
        ends = _ends(L)
        path = cache_dir() / "windows" / f"{_slug(name)}_protect_w{WIN_LEN}_s{WIN_STEP}_B{WIN_B}{_lim(WIN_MAX)}.csv"
        jobs = [(L.index[e - 1], L.values[e - WIN_LEN:e], _window_seed(i, j), WIN_B) for j, e in enumerate(ends)]
        ext = cached_csv(path, lambda: pd.DataFrame(pmap(_window_extra, jobs)).set_index("end"),
                         index_col=0, parse_dates=True)
        b = base[name].copy()
        b.index, ext.index = pd.to_datetime(b.index), pd.to_datetime(ext.index)
        out[name] = b.join(ext[[c for c in ext.columns if c not in b.columns]], how="inner")
        log(f"window protections {name}: {len(out[name])}")
    return out


def _full_extra(name, x, seed, B):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        return {"series": name, **extra_estimates(x), **shape_bound(x, np.random.default_rng(seed), B)}


def run_full_protections():
    """Protections and the shape bound on each full market series (for ratios to the full sample)."""
    def compute():
        jobs = [(nm, l.dropna().values, 172000 + i, WIN_B) for i, (nm, l) in enumerate(window_series().items())]
        return pd.DataFrame(pmap(_full_extra, jobs))
    lv = run_levels()
    key = {"S&P 500": "S&P 500: full_sample", **{a: f"Panel: {a}" for a in ASSETS}}
    ext = cached_csv(cache_dir() / "windows" / f"full_protect_B{WIN_B}.csv", compute).set_index("series")
    base = lv.set_index("sample")
    rows = []
    for nm in ext.index:
        r = base.loc[key[nm]].to_dict() if key[nm] in base.index else {}
        r.update(ext.loc[nm].to_dict())
        rows.append({"series": nm, **r})
    return pd.DataFrame(rows).set_index("series")


# ----------------------------------------------------------------------------------------
# GARCH-filtered windows
# ----------------------------------------------------------------------------------------
def _window_filtered(end, x, nxt, seed, B):
    """Fit GARCH(1,1)-t to the window, estimate the tail of the standardized losses with every
    method, and score one-step conditional (VaR, ES) forecasts on the following days."""
    out = {"end": end}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            g = fit_garch_t(x)
        except Exception:
            out["garch_ok"] = False
            return out
        z = np.asarray(standardized_losses(x, g), dtype=float)
        z = z[np.isfinite(z)]
        out["garch_ok"] = bool(g.get("success", True))
        out.update(estimate_all(z, np.random.default_rng(seed + FILTER_SEED_SHIFT), B))
        out.update(extra_estimates(z))
        out.update(shape_bound(z, np.random.default_rng(seed + FILTER_SEED_SHIFT), B))
        out.update({f"emp_es{a}": empirical_es(z, a) for a in OOS_LEVELS})
        if len(nxt):
            s = np.sqrt(_sigma2_path(np.concatenate([x, nxt]), g))[len(x):len(x) + len(nxt)]
            mu = float(g["mu"])
            for a in OOS_LEVELS:
                for m in MKT_METHODS:
                    qv, qe = out.get(f"{m}_var{a}", np.nan), out.get(f"{m}_es{a}", np.nan)
                    if m == "tpw" and not np.isfinite(qe):
                        qv, qe = out.get(f"tpw_core_var{a}", np.nan), out.get(f"tpw_core_es{a}", np.nan)
                    if not (np.isfinite(qv) and np.isfinite(qe)):
                        qv, qe = out.get(f"ew_var{a}", np.nan), out.get(f"ew_es{a}", np.nan)
                    v, e = mu + s * qv, mu + s * qe
                    with np.errstate(all="ignore"):
                        sc = (nxt > v) * (nxt - v) / ((1 - a) * e) + v / e + np.log(e) - 1
                    out[f"fz0_{m}_{a}"] = float(np.mean(sc)) if np.all(e > 0) and np.isfinite(sc).all() else np.nan
    return out


def run_window_filtered():
    """{series: frame} for the GARCH-filtered windows (same windows and resampling streams shifted
    by FILTER_SEED_SHIFT)."""
    out = {}
    for i, (name, losses) in enumerate(window_series().items()):
        L = losses.dropna()
        ends = _ends(L)
        path = cache_dir() / "windows" / f"{_slug(name)}_filtered_w{WIN_LEN}_s{WIN_STEP}_B{WIN_B}{_lim(WIN_MAX)}.csv"
        jobs = [(L.index[e - 1], L.values[e - WIN_LEN:e], L.values[e:e + WIN_STEP], _window_seed(i, j), WIN_B)
                for j, e in enumerate(ends)]
        df = cached_csv(path, lambda: pd.DataFrame(pmap(_window_filtered, jobs)).set_index("end"),
                        index_col=0, parse_dates=True)
        df.index = pd.to_datetime(df.index)
        out[name] = df
        log(f"filtered windows {name}: {len(df)}")
    return out


# ----------------------------------------------------------------------------------------
# Tables
# ----------------------------------------------------------------------------------------
def _stability_rows(name, df, meas, full=None):
    M = _with_fallback(df, meas)
    a = float(meas[2:])
    emp = df[f"emp_es{a}"] if f"emp_es{a}" in df else None
    flag = (df["xi_U90_mid"] >= 1) if "xi_U90_mid" in df else pd.Series(False, index=df.index)
    rows = []
    for m in MKT_METHODS:
        v = M[m]
        ch = v.pct_change(fill_method=None).abs().dropna() * 100
        r = {"series": name, "method": MKT_LABELS[m], "windows": len(v), "flagged_%": 100 * float(flag.mean()),
             "mean_abs_change_%": float(ch.mean()), "changes_over_25%": int((ch > 25).sum()),
             "changes_over_2x": int((np.abs(np.log(v / v.shift())) > np.log(2)).sum())}
        if full is not None:
            f0 = full.get(f"{m}_{meas}", np.nan)
            if m == "tpw" and not np.isfinite(f0):
                f0 = full.get(f"tpw_core_{meas}", np.nan)
            if not np.isfinite(f0):
                f0 = full.get(f"ew_{meas}", np.nan)
            r["largest_ratio_to_full"] = float((v / f0).max()) if np.isfinite(f0) else np.nan
        if emp is not None:
            ratio = v / emp
            r["largest_ratio_to_empirical"] = float(ratio.max())
            r["windows_above_2x_empirical_%"] = 100 * float((ratio > 2).mean())
            r["windows_below_empirical_%"] = 100 * float((ratio < 1).mean())
        rows.append(r)
    return rows


def _all_series_rows(t):
    """Pool the per-series rows of each method: counts summed, shares weighted by windows, maxima of maxima."""
    rows = []
    for m, g in t.groupby("method", sort=False):
        w = g["windows"]
        r = {"series": "All series", "method": m, "windows": int(w.sum())}
        for c in g.columns:
            if c in ("series", "method", "windows"):
                continue
            if c.startswith("largest"):
                r[c] = float(g[c].max())
            elif c.startswith("changes"):
                r[c] = int(g[c].sum())
            else:
                r[c] = float(np.average(g[c], weights=w))
        rows.append(r)
    return rows


def market_windows_stability(frames, full=None, meas="es0.99"):
    rows = []
    for name, df in frames.items():
        f = full.loc[name].to_dict() if full is not None and name in full.index else None
        rows += _stability_rows(ASSET_NAMES.get(name, name), df, meas, f)
    t = pd.DataFrame(rows)
    return pd.concat([t, pd.DataFrame(_all_series_rows(t))], ignore_index=True)


def market_windows_by_flag(frames, meas="es0.99"):
    """Pooled over series: windows with and without the shape-bound flag, by method."""
    a = float(meas[2:])
    rows = []
    for flagged in (False, True):
        parts = []
        for df in frames.values():
            M = _with_fallback(df, meas)
            sel = (df["xi_U90_mid"] >= 1) == flagged
            parts.append((M[sel].div(df.loc[sel, f"emp_es{a}"], axis=0)))
        R = pd.concat(parts)
        for m in MKT_METHODS:
            rows.append({"windows": "flagged" if flagged else "not flagged", "n_windows": len(R), "method": MKT_LABELS[m],
                         "median_ratio_to_empirical": float(R[m].median()),
                         "largest_ratio_to_empirical": float(R[m].max()) if len(R) else np.nan,
                         "above_2x_empirical_%": 100 * float((R[m] > 2).mean()) if len(R) else np.nan,
                         "below_empirical_%": 100 * float((R[m] < 1).mean()) if len(R) else np.nan})
    return pd.DataFrame(rows)


def _oos_unconditional(name, df, losses, a):
    """FZ0 score of each window's unconditional (VaR, ES) on the losses of the next 21 days."""
    L = losses.dropna()
    pos = {d: k for k, d in enumerate(pd.to_datetime(L.index))}
    V, E = _with_fallback(df, f"var{a}"), _with_fallback(df, f"es{a}")
    S = {}
    for m in MKT_METHODS:
        sc = []
        for d in df.index:
            k = pos.get(pd.Timestamp(d))
            nxt = L.values[k + 1:k + 1 + WIN_STEP] if k is not None else np.array([])
            sc.append(fz0(nxt, V.at[d, m], E.at[d, m], a) if len(nxt) else np.nan)
        S[m] = np.array(sc)
    return S


def _oos_rows(name, S, a):
    rows = []
    for m in MKT_METHODS:
        d = S[m] - S["ew"]
        T, md, p = nw_dm(d)
        rows.append({"series": name, "level": a, "method": MKT_LABELS[m], "windows": int(np.isfinite(d).sum()),
                     "mean_fz0": float(np.nanmean(S[m])), "diff_vs_ew": float(np.nanmean(d)) if np.isfinite(d).any() else np.nan,
                     "windows_better_%": 100 * float(np.nanmean(d[np.isfinite(d)] < -1e-12)) if np.isfinite(d).any() else np.nan,
                     "dm_p": p})
    return rows


def market_windows_oos(frames, series):
    rows = []
    for name, df in frames.items():
        for a in OOS_LEVELS:
            rows += _oos_rows(ASSET_NAMES.get(name, name), _oos_unconditional(name, df, series[name], a), a)
    return pd.DataFrame(rows)


def market_filtered_oos(frames):
    rows = []
    for name, df in frames.items():
        for a in OOS_LEVELS:
            S = {m: df[f"fz0_{m}_{a}"].values.astype(float) if f"fz0_{m}_{a}" in df else np.full(len(df), np.nan)
                 for m in MKT_METHODS}
            rows += _oos_rows(ASSET_NAMES.get(name, name), S, a)
    return pd.DataFrame(rows)


def regime_summary(unc, filt, full):
    """One row per data set: sample regime, number of samples, share flagged by the shape bound,
    largest ratio to the full-sample estimate (unprotected = worst of EW, CV-BMA and VPW;
    protected = worst of the median, screened EW, capped shape and TPW), and the share of samples
    in which penalized likelihood falls below the empirical 99% ES."""
    rows = []
    if full is not None:
        lens = {nm: int(l.dropna().size) for nm, l in window_series().items()}
        es = full[[f"{m}_es0.99" for m in ("ew", "cv", "tpw", "median", "screen", "pen") if f"{m}_es0.99" in full]]
        spread = 100 * (es.max(axis=1) / es.min(axis=1) - 1)
        rows.append({"regime": "Long samples", "data": "Six market series, full sample",
                     "obs_per_sample": f"{min(lens.values()):,}-{max(lens.values()):,}", "samples": len(full),
                     "flagged_%": 100 * float((full["xi_U90_mid"] >= 1).mean()),
                     "largest_ratio_unprotected": np.nan, "largest_ratio_protected": np.nan,
                     "pen_below_empirical_%": np.nan,
                     "note": f"99% ES of the methods differs by at most {spread.max():.1f}%"})
    for lab, frames in (("One-year windows", unc), ("One-year windows, GARCH-filtered", filt)):
        if not frames:
            continue
        t = market_windows_stability(frames, full if lab == "One-year windows" else None)
        a = t[t.series == "All series"].set_index("method")
        col = "largest_ratio_to_full" if lab == "One-year windows" else "largest_ratio_to_empirical"
        rows.append({"regime": lab, "data": "Six market series, 250-day windows every 21 days",
                     "obs_per_sample": "250", "samples": int(a.loc["Equal weights", "windows"]),
                     "flagged_%": float(a.loc["Equal weights", "flagged_%"]),
                     "largest_ratio_unprotected": float(a.loc[["Equal weights", "CV-BMA", "VPW"], col].max()),
                     "largest_ratio_protected": float(a.loc[["Median", "Screened EW", "Capped shape", "TPW"], col].max()),
                     "pen_below_empirical_%": float(a.loc["Penalized", "windows_below_empirical_%"]),
                     "note": "ratios to the full-sample estimate" if col == "largest_ratio_to_full"
                     else "ratios to the window's empirical ES of the standardized losses"})
    p = table_dir() / "data_stability.csv"
    if p.exists():
        S = pd.read_csv(p)
        kind = {"Danish": "Annual insurance losses", "Norwegian": "Annual insurance losses",
                "French fire": "Annual insurance losses", "BMW": "Annual equity losses", "Siemens": "Annual equity losses"}
        for nm, g in S.groupby("data", sort=False):
            g = g.set_index("method")
            yrs = int(g["years"].iloc[0])
            rows.append({"regime": kind.get(nm, "Annual losses"), "data": nm, "obs_per_sample": "one year", "samples": yrs,
                         "flagged_%": 100 * float(g["flagged"].iloc[0]) / yrs,
                         "largest_ratio_unprotected": float(g.loc[[m for m in ("ew", "cv", "vpw") if m in g.index], "maxratio"].max()),
                         "largest_ratio_protected": float(g.loc[[m for m in ("median", "screen", "cap", "tpw") if m in g.index], "maxratio"].max()),
                         "pen_below_empirical_%": 100 * float(g.loc["pen", "below_emp"]) / yrs if "pen" in g.index else np.nan,
                         "note": "ratios to the full-sample estimate"})
    return pd.DataFrame(rows)


def step_market_regimes():
    """Market windows with every protection, the shape-bound check, out-of-sample scores and the
    GARCH-filtered variant, and a summary of every data set by sample regime. Run after Step 13
    (the summary reads its loss-data stability table)."""
    series = window_series()
    full = run_full_protections()
    unc = run_window_protections()
    filt = run_window_filtered()
    out = {"market_windows_stability_es99": market_windows_stability(unc, full, "es0.99"),
           "market_windows_stability_es975": market_windows_stability(unc, full, "es0.975"),
           "market_windows_by_flag_es99": market_windows_by_flag(unc, "es0.99"),
           "market_windows_out_of_sample": market_windows_oos(unc, series),
           "market_filtered_stability_es99": market_windows_stability(filt, None, "es0.99"),
           "market_filtered_by_flag_es99": market_windows_by_flag(filt, "es0.99"),
           "market_filtered_out_of_sample": market_filtered_oos(filt),
           "regime_summary": regime_summary(unc, filt, full)}
    return _save_all(out)


# ---- run and show the results
r = RESULTS["market_regimes"] = step_market_regimes()
for k in ("regime_summary", "market_windows_by_flag_es99", "market_filtered_by_flag_es99"):
    print(k); display(r[k].round(2))
for k in ("market_windows_stability_es99", "market_filtered_stability_es99"):
    print(k); display(r[k][r[k].series == "All series"].round(2))
for k in ("market_windows_out_of_sample", "market_filtered_out_of_sample"):
    t = r[k]
    print(k, "- mean FZ0 difference from equal weights, averaged over the series (negative is better)")
    display(t.pivot_table(index="method", columns="level", values="diff_vs_ew", aggfunc="mean").round(4))
    print("series in which the Diebold-Mariano test rejects equal accuracy with EW at 5%")
    display(t[t.dm_p < 0.05][["series", "level", "method", "diff_vs_ew", "dm_p"]].round(4))

