import platform
import shutil
import subprocess
import sys
import zipfile
from pathlib import Path

import pandas as pd

ROOT = Path.cwd()
CACHE = ROOT / "outputs" / "cache" / "full"
STORE = ROOT / "data" / "published_rules"
STORE.mkdir(parents=True, exist_ok=True)
assert CACHE.exists(), f"{CACHE} not found: run this from the project folder of the complete run"

# 1. R results -> data/published_rules/ (the names load_rcomp() and r_results() look for)
jobs = {"rcomp_out": "stress_results.csv",
        "rcomp_danish_out": "danish_results.csv",
        "rcomp_norwegian_out": "norwegian_results.csv",
        "rcomp_norfire_real_out": "norfire_real_results.csv",
        "checks/eqd_data_out": "eqd_data_results.csv",
        "checks/eqd_stress_out": "eqd_stress_results.csv",
        "checks/bayes_new_out": "bayes_new_data_results.csv"}
missing = []
for sub, name in jobs.items():
    parts = sorted((CACHE / sub).glob("part*.csv"))
    if not parts:
        missing.append(sub)
        continue
    df = pd.concat([pd.read_csv(p) for p in parts], ignore_index=True)
    df.to_csv(STORE / name, index=False)
    print(f"{sub:28s} -> data/published_rules/{name}  ({len(df)} rows)")
if missing:
    print("\nWARNING: no R results in", missing, "- these jobs did not finish in this run")

# 2. Software versions
lines = ["SOFTWARE VERSIONS", "", "Python " + sys.version.split()[0], "Platform " + platform.platform(), ""]
for pkg in ("numpy", "scipy", "pandas", "matplotlib", "joblib", "yfinance", "rdata"):
    try:
        lines.append(f"{pkg} {importlib.import_module(pkg).__version__}")
    except Exception:
        lines.append(f"{pkg} not installed")
r = subprocess.run(["Rscript", "-e",
                    'for (p in c("threshr", "eva", "mev", "revdbayes", "rust")) '
                    'cat(p, if (requireNamespace(p, quietly = TRUE)) as.character(packageVersion(p)) else "not installed", "\\n"); '
                    'cat("\\n"); suppressMessages({library(threshr); library(eva); library(mev)}); print(sessionInfo())'],
                   capture_output=True, text=True)
lines += ["", "R packages used by the benchmarks", r.stdout, r.stderr.strip()]
(ROOT / "software_versions.txt").write_text("\n".join(lines), encoding="utf-8")
print("\n".join(lines[:30]))

# 3. Zip: stored results, raw R outputs and logs, the R scripts, versions and the manifest
zpath = Path("/content/r_results_and_versions.zip")
with zipfile.ZipFile(zpath, "w", zipfile.ZIP_DEFLATED) as z:
    for f in sorted(STORE.glob("*.csv")):
        z.write(f, f"data/published_rules/{f.name}")
    for sub in jobs:
        for f in sorted((CACHE / sub).glob("*")):
            z.write(f, f"outputs/cache/full/{sub}/{f.name}")
    for f in sorted((ROOT / "R").glob("*.R")):
        z.write(f, f"R/{f.name}")
    z.write(ROOT / "software_versions.txt", "software_versions.txt")
    man = ROOT / "outputs" / "manifest_full.json"
    if man.exists():
        z.write(man, "outputs/manifest_full.json")
print(f"\n{zpath} written ({zpath.stat().st_size / 1e6:.1f} MB)")

if Path("/content/drive/MyDrive").exists():
    shutil.copy(zpath, "/content/drive/MyDrive/r_results_and_versions.zip")
    print("copied to Google Drive: MyDrive/r_results_and_versions.zip")
from google.colab import files
files.download(str(zpath))
